/* ==========================================================================
   WILDBOUND — base, chrome, title, prologue
   ========================================================================== */

@font-face {
  font-family: 'Cinzel';
  font-style: normal;
  font-weight: 400 900;
  font-display: swap;
  src: url('assets/fonts/cinzel.woff2') format('woff2');
}
@font-face {
  font-family: 'Outfit';
  font-style: normal;
  font-weight: 100 900;
  font-display: swap;
  src: url('assets/fonts/outfit.woff2') format('woff2');
}

:root {
  --serif: 'Cinzel', 'Iowan Old Style', 'Palatino Linotype', Georgia, serif;
  --sans: 'Outfit', 'Avenir Next', 'Segoe UI', system-ui, sans-serif;

  --bg: #080b12;
  --bg-2: #0b111b;
  --panel: rgba(17, 24, 37, 0.78);
  --panel-solid: #111825;
  --panel-2: rgba(23, 32, 48, 0.7);
  --line: rgba(255, 235, 200, 0.11);
  --line-strong: rgba(255, 235, 200, 0.22);
  --gold: #f2c179;
  --gold-bright: #ffe3a8;
  --gold-deep: #b97c36;
  --teal: #7fd8d2;
  --rose: #ff9fc4;
  --red: #ff7d7d;
  --green: #8fe2a6;
  --text: #f1e9db;
  --muted: #b0a798;
  --dim: #7d776e;
  --ink: #090d15;
  --topbar: 64px;
  --radius: 14px;
  --shadow: 0 24px 50px rgba(0, 0, 0, 0.45);
  --glow-gold: 0 0 24px rgba(242, 193, 121, 0.28);
}

* { box-sizing: border-box; }

html, body { margin: 0; padding: 0; min-height: 100%; }

html {
  background: var(--bg);
  -webkit-text-size-adjust: 100%;
  text-size-adjust: 100%;
}

body {
  min-height: 100vh;
  min-height: 100dvh;
  overflow: hidden;
  font-family: var(--sans);
  font-size: 15px;
  line-height: 1.5;
  color: var(--text);
  background: radial-gradient(120% 90% at 50% -10%, #162033 0%, #0a0f18 48%, #06090f 100%);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overscroll-behavior: none;
}

body::before {
  content: '';
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 0;
  opacity: 0.5;
  background-image:
    radial-gradient(1px 1px at 20% 24%, rgba(255, 240, 208, 0.35), transparent 60%),
    radial-gradient(1px 1px at 74% 12%, rgba(255, 240, 208, 0.28), transparent 60%),
    radial-gradient(1px 1px at 47% 42%, rgba(255, 240, 208, 0.2), transparent 60%);
  background-size: 340px 280px, 470px 360px, 290px 240px;
}

#app {
  position: relative;
  z-index: 1;
  height: 100vh;
  height: 100dvh;
  overflow: hidden;
}

#fx-layer {
  position: fixed;
  inset: 0;
  z-index: 400;
  overflow: hidden;
  pointer-events: none;
}

#toast-layer {
  position: fixed;
  top: calc(env(safe-area-inset-top, 0px) + 14px);
  left: 50%;
  transform: translateX(-50%);
  z-index: 600;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  width: min(92vw, 460px);
  pointer-events: none;
}

h1, h2, h3, h4, p { margin: 0; }
button { font: inherit; color: inherit; }
button, [role='button'] { -webkit-tap-highlight-color: transparent; }
img, svg { max-width: 100%; }
a { color: var(--gold); }
::selection { background: rgba(242, 193, 121, 0.3); color: #fff; }

:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 3px;
}

::-webkit-scrollbar { width: 9px; height: 9px; }
::-webkit-scrollbar-track { background: rgba(0, 0, 0, 0.2); }
::-webkit-scrollbar-thumb {
  background: rgba(242, 193, 121, 0.22);
  border-radius: 20px;
  border: 2px solid transparent;
  background-clip: content-box;
}
::-webkit-scrollbar-thumb:hover { background-color: rgba(242, 193, 121, 0.4); }

.ico {
  width: 1em;
  height: 1em;
  display: inline-block;
  flex: none;
  vertical-align: -0.14em;
  overflow: visible;
}
.art-svg { display: block; width: 100%; height: auto; overflow: visible; }

.eyebrow {
  font-family: var(--sans);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: var(--gold);
}

.display {
  font-family: var(--serif);
  font-weight: 700;
  font-size: clamp(34px, 5vw, 58px);
  line-height: 1.04;
  letter-spacing: 0.005em;
  color: #fbf2df;
  text-wrap: balance;
}
.display.small { font-size: clamp(26px, 3.4vw, 40px); }

.fine { font-size: 12px; color: var(--dim); }
.empty-note {
  color: var(--dim);
  font-size: 13px;
  line-height: 1.45;
  font-style: italic;
}
.empty-note.center { text-align: center; max-width: 440px; margin: 20px auto 0; }
.noscript {
  display: grid;
  place-items: center;
  height: 100dvh;
  color: var(--gold);
  font-family: var(--serif);
  font-size: 22px;
  padding: 30px;
  text-align: center;
}

/* ---------------------------------------------------------------- buttons */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.55em;
  min-height: 44px;
  padding: 10px 18px;
  border-radius: 10px;
  border: 1px solid var(--line-strong);
  background: linear-gradient(180deg, #1b2433, #101724);
  color: var(--text);
  font-family: var(--sans);
  font-size: 14px;
  font-weight: 600;
  letter-spacing: 0.02em;
  cursor: pointer;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.07), 0 8px 20px rgba(0, 0, 0, 0.28);
  transition: transform 0.18s ease, border-color 0.18s ease, background 0.18s ease, box-shadow 0.18s ease;
}
.btn:hover:not(:disabled) {
  transform: translateY(-1px);
  border-color: rgba(242, 193, 121, 0.52);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.09), 0 10px 24px rgba(0, 0, 0, 0.34);
}
.btn:active:not(:disabled) { transform: translateY(0) scale(0.99); }
.btn:disabled { opacity: 0.38; cursor: not-allowed; }
.btn .ico { font-size: 1.12em; }

.btn.primary {
  border-color: rgba(255, 231, 184, 0.72);
  background: linear-gradient(180deg, #ffe0a0 0%, #efba69 52%, #d3953f 100%);
  color: #24160a;
  text-shadow: 0 1px 0 rgba(255, 255, 255, 0.24);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.45), 0 10px 28px rgba(219, 158, 70, 0.24);
}
.btn.primary:hover:not(:disabled) {
  border-color: #fff1cd;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.5), 0 12px 34px rgba(234, 174, 82, 0.34);
}
.btn.ghost {
  background: rgba(242, 193, 121, 0.04);
  border-color: rgba(242, 193, 121, 0.5);
  color: var(--gold-bright);
}
.btn.quiet {
  background: transparent;
  border-color: transparent;
  color: var(--muted);
  box-shadow: none;
}
.btn.quiet:hover:not(:disabled) {
  color: var(--text);
  background: rgba(255, 255, 255, 0.04);
  border-color: var(--line);
}
.btn.danger {
  border-color: rgba(255, 125, 125, 0.4);
  background: rgba(255, 100, 100, 0.08);
  color: #ffb3b3;
}
.btn.big { min-height: 52px; padding: 13px 27px; font-size: 15px; border-radius: 12px; }
.btn.small { min-height: 34px; padding: 5px 12px; font-size: 12px; border-radius: 8px; }

.text-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 3px 0;
  border: 0;
  background: none;
  color: var(--gold);
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.06em;
  cursor: pointer;
}
.text-btn .ico { font-size: 10px; transition: transform 0.18s ease; }
.text-btn:hover { color: var(--gold-bright); }
.text-btn:hover .ico { transform: translateX(3px); }

kbd {
  display: inline-grid;
  place-items: center;
  min-width: 20px;
  height: 19px;
  padding: 0 5px;
  border-radius: 4px;
  border: 1px solid rgba(255, 255, 255, 0.16);
  border-bottom-width: 2px;
  background: rgba(255, 255, 255, 0.06);
  font-family: var(--sans);
  font-size: 10px;
  font-weight: 600;
  color: var(--muted);
}

/* ----------------------------------------------------------------- topbar */

.app-shell {
  height: 100vh;
  height: 100dvh;
  display: flex;
  flex-direction: column;
  min-height: 0;
}

.topbar {
  position: relative;
  z-index: 30;
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: clamp(10px, 2vw, 26px);
  min-height: calc(var(--topbar) + env(safe-area-inset-top, 0px));
  padding: env(safe-area-inset-top, 0px) max(14px, env(safe-area-inset-right, 0px)) 0 max(14px, env(safe-area-inset-left, 0px));
  border-bottom: 1px solid var(--line);
  background: linear-gradient(180deg, rgba(10, 15, 24, 0.94), rgba(9, 13, 21, 0.82));
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  padding: 5px 6px 5px 0;
  border: 0;
  background: none;
  color: var(--gold);
  cursor: pointer;
  flex: none;
}
.brand-mark {
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  border-radius: 50%;
  background: radial-gradient(circle at 38% 32%, #fff2c5, #f0b85f 58%, #9a5a20);
  color: #3c2209;
  box-shadow: 0 0 18px rgba(242, 193, 121, 0.32), inset 0 1px 2px #fff8;
}
.brand-mark .ico { width: 17px; height: 17px; stroke-width: 2.2; }
.brand-word {
  font-family: var(--serif);
  font-weight: 700;
  font-size: 16px;
  letter-spacing: 0.17em;
  color: #f7e8cb;
}

.hud {
  display: flex;
  align-items: center;
  gap: clamp(8px, 1.5vw, 20px);
  min-width: 0;
}
.hud-hp, .hud-gold, .hud-floor {
  display: flex;
  align-items: center;
  gap: 7px;
  font-size: 13px;
  color: var(--muted);
  white-space: nowrap;
}
.hud-hp > .ico { color: #ff9aa0; font-size: 15px; }
.hud-gold > .ico { color: var(--gold); font-size: 15px; }
.hud-floor > .ico { color: var(--teal); font-size: 15px; }
.hud b { color: var(--text); font-weight: 600; font-size: 14px; }
.hud i { font-style: normal; color: var(--dim); font-size: 11px; }
.hud-hpbar {
  width: clamp(50px, 7vw, 94px);
  height: 6px;
  border-radius: 8px;
  background: #1a1219;
  border: 1px solid rgba(255, 255, 255, 0.07);
  overflow: hidden;
}
.hud-hpbar span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #d96772, #ff9a9a);
  box-shadow: 0 0 8px rgba(255, 130, 140, 0.5);
}

.hud-actions {
  display: flex;
  align-items: center;
  gap: 5px;
  margin-left: auto;
}
.hud-btn {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  min-height: 38px;
  padding: 6px 11px;
  border: 1px solid transparent;
  border-radius: 9px;
  background: transparent;
  color: var(--muted);
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
  transition: 0.16s ease;
}
.hud-btn .ico { font-size: 16px; color: var(--gold); opacity: 0.85; }
.hud-btn b {
  font-weight: 600;
  font-size: 11px;
  color: var(--gold-bright);
  background: rgba(242, 193, 121, 0.12);
  border-radius: 5px;
  padding: 1px 5px;
}
.hud-btn:hover { background: rgba(255, 255, 255, 0.045); border-color: var(--line); color: var(--text); }
.hud-btn.icon-only { padding: 7px 9px; }
.hud-btn.icon-only .ico { font-size: 18px; }

.screen {
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
  overscroll-behavior: contain;
}

/* ------------------------------------------------------------------ title */

.title-screen {
  position: relative;
  height: 100vh;
  height: 100dvh;
  min-height: 100%;
  overflow: hidden auto;
  display: flex;
  flex-direction: column;
  background: #070a11;
  isolation: isolate;
}
.title-sky {
  position: absolute;
  inset: 0;
  z-index: 0;
  overflow: hidden;
  background:
    radial-gradient(80% 52% at 68% 8%, rgba(48, 61, 88, 0.75) 0%, transparent 62%),
    radial-gradient(110% 80% at 50% 100%, rgba(74, 45, 45, 0.24) 0%, transparent 58%),
    linear-gradient(180deg, #0a1222 0%, #0c1526 34%, #0a111d 62%, #070a11 100%);
}
.title-sky::before {
  content: '';
  position: absolute;
  inset: 0;
  opacity: 0.65;
  background-image:
