    radial-gradient(1.4px 1.4px at 46% 37%, rgba(255, 244, 214, 0.3), transparent 60%),
    radial-gradient(1px 1px at 84% 46%, rgba(255, 244, 214, 0.35), transparent 60%);
  background-size: 290px 240px, 430px 330px, 350px 270px, 510px 410px;
