}
.title-ridge.r3 {
  height: 21%;
  background: #060a11;
  clip-path: polygon(0 100%, 0 70%, 5% 55%, 10% 69%, 17% 52%, 23% 71%, 31% 58%, 39% 74%, 48% 55%, 57% 72%, 66% 56%, 75% 73%, 83% 55%, 91% 70%, 100% 57%, 100% 100%);
}
.title-trees {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 19%;
  background: #05080d;
  clip-path: polygon(0 100%, 0 54%, 2% 62%, 3% 30%, 4% 62%, 6% 48%, 7% 17%, 8% 51%, 10% 66%, 12% 38%, 13% 8%, 14% 44%, 16% 61%, 18% 30%, 19% 1%, 20% 36%, 22% 59%, 24% 44%, 25% 13%, 26% 48%, 28% 64%, 30% 41%, 31% 6%, 32% 42%, 34% 63%, 36% 47%, 37% 19%, 38% 52%, 40% 66%, 42% 36%, 43% 4%, 44% 40%, 46% 61%, 48% 45%, 49% 14%, 50% 48%, 52% 64%, 54% 39%, 55% 8%, 56% 42%, 58% 62%, 60% 48%, 61% 20%, 62% 53%, 64% 67%, 66% 37%, 67% 5%, 68% 41%, 70% 62%, 72% 46%, 73% 16%, 74% 50%, 76% 65%, 78% 40%, 79% 9%, 80% 44%, 82% 63%, 84% 48%, 85% 19%, 86% 52%, 88% 66%, 90% 38%, 91% 7%, 92% 42%, 94% 62%, 96% 45%, 97% 15%, 98% 48%, 99% 64%, 100% 50%, 100% 100%);
}
.title-screen::after {
  content: '';
  position: absolute;
  left: 50%;
  bottom: -12%;
  width: 72vw;
  height: 44vh;
  transform: translateX(-50%);
  background: radial-gradient(ellipse at center, rgba(242, 176, 92, 0.13), transparent 64%);
  z-index: 1;
  pointer-events: none;
}

.title-content {
  position: relative;
  z-index: 4;
  width: min(760px, 100%);
  margin: auto;
  padding: clamp(48px, 9vh, 96px) 22px 26px;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  animation: riseIn 0.9s cubic-bezier(0.2, 0.75, 0.25, 1) both;
}
.title-eyebrow {
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.34em;
  color: rgba(242, 193, 121, 0.72);
  margin-bottom: 14px;
}
.logo {
  font-family: var(--serif);
  font-weight: 800;
  font-size: clamp(56px, 10.2vw, 124px);
  line-height: 0.92;
  letter-spacing: 0.055em;
  margin-left: 0.055em;
  background: linear-gradient(180deg, #fff9e5 4%, #ffe3a4 34%, #e8b05b 58%, #b9782f 78%, #ffdfa0 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  filter: drop-shadow(0 6px 28px rgba(236, 165, 74, 0.25)) drop-shadow(0 1px 0 rgba(255, 255, 255, 0.18));
}
.logo-rule {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  width: min(420px, 78vw);
  margin: 14px 0 10px;
  color: var(--gold);
}
.logo-rule span {
  height: 1px;
  flex: 1;
  background: linear-gradient(90deg, transparent, rgba(242, 193, 121, 0.55));
}
.logo-rule span:last-child { background: linear-gradient(90deg, rgba(242, 193, 121, 0.55), transparent); }
.logo-rule .ico { font-size: 15px; filter: drop-shadow(0 0 8px rgba(242, 193, 121, 0.6)); }
.title-sub {
  font-family: var(--sans);
  font-size: clamp(11px, 1.4vw, 14px);
  font-weight: 500;
  letter-spacing: 0.44em;
  margin-left: 0.44em;
  color: var(--gold-bright);
  text-shadow: 0 0 20px rgba(242, 193, 121, 0.26);
}
.title-lede {
  margin-top: 18px;
  font-size: clamp(14px, 1.6vw, 17px);
  line-height: 1.6;
  color: var(--muted);
  font-weight: 300;
}
.title-buttons {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 11px;
  margin-top: clamp(24px, 4vh, 40px);
  width: min(400px, 100%);
}
.title-buttons .btn.big { width: 100%; }
.title-small-buttons {
  display: flex;
  gap: 6px;
  justify-content: center;
  margin-top: 5px;
}
.title-small-buttons .btn { min-height: 38px; font-size: 12.5px; padding: 7px 12px; }
.title-meta {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  justify-content: center;
  gap: 10px;
  margin-top: 24px;
  font-size: 11.5px;
  letter-spacing: 0.04em;
  color: var(--dim);
}
.title-meta b { color: var(--muted); font-weight: 600; }
.title-meta .dot { width: 3px; height: 3px; border-radius: 50%; background: var(--gold-deep); opacity: 0.8; }
.title-footer {
  position: relative;
  z-index: 4;
  display: flex;
  justify-content: space-between;
  gap: 14px;
  padding: 12px max(18px, env(safe-area-inset-right, 0px)) calc(12px + env(safe-area-inset-bottom, 0px)) max(18px, env(safe-area-inset-left, 0px));
  font-size: 10.5px;
  color: #69645d;
  letter-spacing: 0.03em;
}
.title-footer span { display: inline-flex; align-items: center; gap: 6px; }
.title-footer .ico { color: #8b7b5d; }
.title-version { white-space: nowrap; font-variant-numeric: tabular-nums; }
.title-creature {
  position: absolute;
  z-index: 2;
  bottom: 3%;
  width: clamp(150px, 17vw, 250px);
  opacity: 0.9;
  filter: drop-shadow(0 24px 24px rgba(0, 0, 0, 0.55));
  animation: floaty 7s ease-in-out infinite;
  pointer-events: none;
}
.title-creature.left { left: 1.5%; }
.title-creature.right { right: 1.5%; animation-delay: -2.4s; }
.title-creature.small {
  width: clamp(82px, 8.5vw, 126px);
  left: 24%;
  bottom: 1%;
  opacity: 0.55;
  animation-delay: -4.4s;
}
.firefly {
  position: absolute;
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: #ffe9a8;
  box-shadow: 0 0 8px 2px rgba(255, 204, 102, 0.5);
  opacity: 0;
  animation: firefly 9s ease-in-out infinite;
  pointer-events: none;
  z-index: 3;
}

/* --------------------------------------------------------------- prologue */

.prologue-screen {
  position: relative;
  height: 100vh;
  height: 100dvh;
  overflow: hidden auto;
  display: flex;
  flex-direction: column;
  background:
    radial-gradient(80% 60% at 80% 10%, rgba(55, 60, 84, 0.5), transparent 62%),
    linear-gradient(180deg, #0a1322 0%, #0a101c 55%, #06090f 100%);
  isolation: isolate;
}
.prologue-sky { position: absolute; inset: 0; z-index: 0; overflow: hidden; }
.prologue-sky > svg {
  position: absolute;
  top: 3%;
  right: 8%;
  width: clamp(120px, 15vw, 200px);
  opacity: 0.7;
  filter: drop-shadow(0 0 36px rgba(255, 234, 180, 0.15));
}
.prologue-ridge {
  position: absolute;
  left: -3%;
  right: -3%;
  bottom: 0;
  height: 35%;
  background: #080d16;
  clip-path: polygon(0 100%, 0 70%, 7% 48%, 14% 66%, 22% 38%, 30% 64%, 38% 45%, 47% 70%, 56% 42%, 64% 63%, 73% 34%, 81% 60%, 90% 44%, 100% 63%, 100% 100%);
  opacity: 0.8;
}
.prologue-screen::after {
  content: '';
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 20%;
  background: linear-gradient(180deg, transparent, #05080d 45%);
  pointer-events: none;
}
.prologue-inner {
  position: relative;
  z-index: 3;
  width: min(700px, 100%);
  padding: clamp(40px, 9vh, 92px) clamp(22px, 6vw, 48px) clamp(36px, 8vh, 76px);
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  animation: riseIn 0.85s cubic-bezier(0.2, 0.75, 0.25, 1) both;
}
.prologue-inner .display { margin-top: 14px; font-size: clamp(42px, 6.4vw, 76px); }
.prologue-copy {
  max-width: 540px;
  margin-top: 22px;
  font-size: clamp(14px, 1.5vw, 16.5px);
  line-height: 1.72;
  color: var(--muted);
  font-weight: 300;
}
.prologue-steps {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
  margin-top: clamp(24px, 4.5vh, 40px);
  width: 100%;
  max-width: 640px;
}
.pstep {
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 14px 13px;
  border-radius: 12px;
  border: 1px solid var(--line);
  background: linear-gradient(165deg, rgba(255, 255, 255, 0.035), rgba(255, 255, 255, 0.008));
}
.pstep-ic {
  display: grid;
  place-items: center;
  width: 32px;
  height: 32px;
  border-radius: 9px;
  margin-bottom: 3px;
  color: var(--gold);
  background: rgba(242, 193, 121, 0.09);
  border: 1px solid rgba(242, 193, 121, 0.18);
}
.pstep-ic .ico { width: 17px; height: 17px; }
.pstep b {
  font-family: var(--serif);
  font-size: 13.5px;
  letter-spacing: 0.08em;
  color: var(--gold-bright);
}
.pstep i {
  font-style: normal;
  font-size: 11.5px;
  line-height: 1.45;
  color: var(--dim);
}
.prologue-actions {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-top: clamp(24px, 4.5vh, 42px);
  align-items: flex-start;
}
.prologue-creature {
  position: absolute;
  z-index: 2;
  right: 2%;
  bottom: 4%;
  width: clamp(240px, 36vw, 560px);
  opacity: 0.9;
  filter: drop-shadow(0 32px 40px rgba(0, 0, 0, 0.6));
  animation: floaty 8s ease-in-out infinite;
  pointer-events: none;
}
.prologue-screen .firefly { z-index: 2; }

/* ------------------------------------------------------------- animations */

@keyframes riseIn {
  from { opacity: 0; transform: translateY(18px); }
  to { opacity: 1; transform: none; }
}
@keyframes floaty {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-9px); }
}
@keyframes moonBreathe {
  0%, 100% { filter: drop-shadow(0 0 34px rgba(255, 234, 180, 0.18)); }
  50% { filter: drop-shadow(0 0 54px rgba(255, 234, 180, 0.28)); }
}
@keyframes cloudDrift {
  from { transform: translateX(-6%); }
  to { transform: translateX(8%); }
}
@keyframes starDrift {
  from { transform: translateY(0); }
  to { transform: translateY(-40px); }
}
@keyframes firefly {
  0% { opacity: 0; transform: translate(0, 0) scale(0.7); }
  12% { opacity: 0.9; }
  50% { opacity: 0.35; transform: translate(24px, -38px) scale(1); }
  80% { opacity: 0.75; }
  100% { opacity: 0; transform: translate(-12px, -84px) scale(0.6); }
}

/* ==========================================================================
   WILDBOUND — cards, health bars, status chips, charms
   ========================================================================== */

/* ------------------------------------------------------------------- card */

.card {
  --el: #ffb26b;
  --el-deep: #6b3724;
  --card-w: 168px;
  position: relative;
  display: flex;
  flex-direction: column;
  width: var(--card-w);
  aspect-ratio: 0.685;
  padding: 5px;
  border: 1px solid color-mix(in srgb, var(--el) 52%, #65594a);
  border-radius: 11px;
  background:
    linear-gradient(160deg, color-mix(in srgb, var(--el) 17%, #1b2230) 0%, #121824 36%, #0b0f17 100%);
  color: #f4ecdf;
  box-shadow:
    0 14px 28px rgba(0, 0, 0, 0.45),
    inset 0 0 0 1px rgba(255, 255, 255, 0.04),
    inset 0 1px 0 rgba(255, 255, 255, 0.1);
  overflow: hidden;
  container-type: inline-size;
  text-align: left;
  cursor: pointer;
  transform: translateZ(0);
  transition: transform 0.18s cubic-bezier(0.2, 0.7, 0.3, 1), box-shadow 0.18s ease, border-color 0.18s ease;
}
button.card { font: inherit; color: #f4ecdf; }
.card::before {
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  border-radius: inherit;
  background:
    linear-gradient(115deg, rgba(255, 255, 255, 0.06), transparent 34%),
    repeating-linear-gradient(115deg, rgba(255, 255, 255, 0.022) 0 1px, transparent 1px 6px);
  opacity: 0.75;
}
.card::after {
  content: '';
  position: absolute;
  inset: 3px;
  border-radius: 8px;
  border: 1px solid color-mix(in srgb, var(--el) 22%, transparent);
  pointer-events: none;
}

.card-cost {
  position: absolute;
  z-index: 5;
  top: 5px;
  left: 5px;
  display: grid;
  place-items: center;
  width: clamp(22px, 21cqw, 36px);
  height: clamp(22px, 21cqw, 36px);
  border-radius: 50%;
  border: 1.5px solid rgba(255, 228, 173, 0.8);
  background: radial-gradient(circle at 38% 30%, #3a4458, #111724 70%);
  color: var(--gold-bright);
  font-family: var(--serif);
  font-size: clamp(12px, 11cqw, 19px);
  font-weight: 700;
  line-height: 1;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.55), inset 0 1px 0 rgba(255, 255, 255, 0.18);
  text-shadow: 0 0 8px rgba(242, 193, 121, 0.45);
}
.card-cost.free { color: #a9f0dc; border-color: rgba(150, 235, 210, 0.7); }
.key-badge {
  position: absolute;
  z-index: 5;
  top: 5px;
  right: 5px;
  display: grid;
  place-items: center;
  width: clamp(15px, 13cqw, 21px);
  height: clamp(15px, 13cqw, 21px);
  border-radius: 5px;
  background: rgba(6, 9, 14, 0.66);
  border: 1px solid rgba(255, 255, 255, 0.14);
  font-size: clamp(7px, 6cqw, 10px);
  font-weight: 600;
  color: var(--muted);
}

.card-art {
  position: relative;
  flex: 0 0 45%;
  border-radius: 7px 7px 4px 4px;
  overflow: hidden;
  background:
    radial-gradient(circle at 50% 46%, color-mix(in srgb, var(--el) 32%, transparent) 0%, transparent 62%),
    linear-gradient(155deg, color-mix(in srgb, var(--el-deep) 60%, #131a26), #0b0f17 82%);
  border: 1px solid color-mix(in srgb, var(--el) 25%, transparent);
  display: grid;
  place-items: center;
}
.card-art::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 55%, rgba(6, 9, 14, 0.5));
}
.art-glow {
  position: absolute;
  width: 68%;
  aspect-ratio: 1;
  border-radius: 50%;
  background: radial-gradient(circle, color-mix(in srgb, var(--el) 42%, transparent) 0%, transparent 66%);
  filter: blur(8px);
}
.art-ring {
  position: absolute;
  width: 50%;
  aspect-ratio: 1;
  border-radius: 50%;
  border: 1px solid color-mix(in srgb, var(--el) 36%, transparent);
  opacity: 0.65;
}
.art-ring.r2 { width: 72%; opacity: 0.3; }
.art-stars {
  position: absolute;
  inset: 0;
  background-image:
    radial-gradient(1px 1px at 22% 28%, color-mix(in srgb, var(--el) 85%, white), transparent 70%),
    radial-gradient(1px 1px at 76% 22%, color-mix(in srgb, var(--el) 70%, white), transparent 70%),
    radial-gradient(1px 1px at 66% 74%, color-mix(in srgb, var(--el) 60%, white), transparent 70%),
    radial-gradient(1px 1px at 30% 70%, color-mix(in srgb, var(--el) 55%, white), transparent 70%);
  opacity: 0.65;
}
.card-glyph { position: relative; z-index: 2; width: 56%; aspect-ratio: 1; color: var(--el); filter: drop-shadow(0 0 12px color-mix(in srgb, var(--el) 45%, transparent)); }
.card-glyph .ico { width: 100%; height: 100%; stroke-width: 1.25; }
.card-kin {
  position: relative;
  z-index: 2;
  width: 88%;
  margin-top: 4%;
  filter: drop-shadow(0 9px 9px rgba(0, 0, 0, 0.42));
}
.card-kin .art-svg { height: 100%; }
.sig-tag {
  position: absolute;
  z-index: 3;
  right: 4px;
  bottom: 4px;
  padding: 1px 4px;
  border-radius: 4px;
  background: rgba(8, 11, 17, 0.7);
  border: 1px solid rgba(255, 159, 196, 0.4);
  color: var(--rose);
  font-size: clamp(4.6px, 4.4cqw, 7px);
  font-weight: 700;
  letter-spacing: 0.16em;
}

.card-body {
  position: relative;
  z-index: 2;
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  flex-direction: column;
  padding: 5px 4px 1px;
}
.card-name {
  font-family: var(--serif);
  font-size: clamp(8.5px, 8.6cqw, 14px);
  font-weight: 700;
  line-height: 1.15;
  letter-spacing: 0.015em;
  color: #fdf5e7;
  overflow: hidden;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
}
.card-name .plus { color: var(--gold); margin-left: 1px; }
.card-type {
  margin-top: 2px;
  font-size: clamp(5px, 5cqw, 7.5px);
  font-weight: 600;
  letter-spacing: 0.13em;
  color: color-mix(in srgb, var(--el) 70%, #c9bfae);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.card-desc {
  margin-top: 4px;
  flex: 1;
  font-size: clamp(7px, 8cqw, 11.5px);
  line-height: 1.28;
  font-weight: 400;
  color: #d9cfc0;
  overflow: hidden;
  display: -webkit-box;
  -webkit-line-clamp: 6;
  -webkit-box-orient: vertical;
}
.card-foot {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-top: 3px;
  padding-top: 3px;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  font-size: clamp(4.6px, 4.5cqw, 7px);
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: #8f887d;
}
.rarity-gem {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--rarity, #74c9c2);
  box-shadow: 0 0 6px var(--rarity, #74c9c2);
  flex: none;
}
.foot-el { margin-left: auto; color: color-mix(in srgb, var(--el) 72%, #8f887d); }

.card.rarity-signature {
  border-color: rgba(255, 159, 196, 0.5);
  box-shadow:
    0 14px 30px rgba(0, 0, 0, 0.48),
    0 0 0 1px rgba(255, 159, 196, 0.1),
    0 0 24px rgba(255, 128, 170, 0.08),
    inset 0 1px 0 rgba(255, 255, 255, 0.1);
}
.card.rarity-rare { border-color: rgba(233, 185, 95, 0.5); }
.card.upgraded .card-name { color: #fff3cf; }
.card.upgraded { box-shadow: 0 14px 30px rgba(0, 0, 0, 0.48), 0 0 0 1px rgba(242, 193, 121, 0.16), inset 0 1px 0 rgba(255, 255, 255, 0.12); }
.card.unplayable { filter: saturate(0.45) brightness(0.72); }
.card.unplayable .card-cost { color: #8f887d; border-color: rgba(255, 255, 255, 0.18); }

.hand-slot .card:hover,
.card-offer .card:hover,
.deck-cell .card:hover,
.shop-item .card:hover,
.single-card-offer .card:hover {
  border-color: color-mix(in srgb, var(--el) 80%, #fff);
  box-shadow: 0 22px 42px rgba(0, 0, 0, 0.58), 0 0 24px color-mix(in srgb, var(--el) 18%, transparent), inset 0 1px 0 rgba(255, 255, 255, 0.14);
}

/* --------------------------------------------------------------- hp bars */

.hpbar {
  --hp: 50%;
  position: relative;
  height: 20px;
  border-radius: 20px;
  background: #1c1318;
  border: 1px solid rgba(255, 255, 255, 0.12);
  box-shadow: inset 0 2px 5px rgba(0, 0, 0, 0.6);
  overflow: visible;
}
.hpbar-fill {
  position: absolute;
  inset: 1px;
  width: var(--hp);
  max-width: calc(100% - 2px);
  border-radius: inherit;
  background: linear-gradient(180deg, #ff9d94 0%, #e2606b 45%, #a52f43 100%);
  box-shadow: 0 0 10px rgba(255, 100, 110, 0.25), inset 0 1px 0 rgba(255, 255, 255, 0.3);
  transition: width 0.45s cubic-bezier(0.2, 0.7, 0.3, 1);
}
.hpbar-shine {
  position: absolute;
  inset: 2px 3px auto;
  height: 35%;
  border-radius: 12px;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.22), transparent);
  pointer-events: none;
}
.hpbar-text {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  font-size: 10.5px;
  font-weight: 600;
  color: #fff;
  letter-spacing: 0.03em;
  text-shadow: 0 1px 2px #000, 0 0 6px #0008;
  font-variant-numeric: tabular-nums;
}
.hpbar-text i { font-style: normal; opacity: 0.55; padding: 0 1px; }
.hpbar.small { height: 15px; }
.hpbar.small .hpbar-text { font-size: 9px; }
.hpbar.wide { width: min(520px, 100%); margin: 2px auto 4px; }
.hpbar-mark {
  position: absolute;
  top: -3px;
  bottom: -3px;
  width: 0;
  border-left: 1.5px dashed rgba(255, 222, 150, 0.9);
  box-shadow: 0 0 8px rgba(255, 211, 120, 0.5);
  pointer-events: none;
}
.hpbar-mark i {
  position: absolute;
  bottom: calc(100% + 2px);
  left: 50%;
  transform: translateX(-50%);
  font-style: normal;
  font-size: 5.5px;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: #ffdf9e;
  white-space: nowrap;
  text-shadow: 0 1px 3px #000;
}

/* ---------------------------------------------------------- status chips */

.status-row {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 4px;
  min-height: 0;
}
.status-row:empty { display: none; }
.status-chip {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 2px;
  padding: 2px 6px 2px 4px;
  border-radius: 20px;
  border: 1px solid color-mix(in srgb, var(--c) 40%, transparent);
  background: color-mix(in srgb, var(--c) 12%, rgba(8, 11, 17, 0.8));
  color: var(--c);
  font-size: 10px;
  font-weight: 600;
  line-height: 1;
  cursor: help;
  outline: none;
}
.status-chip .ico { width: 11px; height: 11px; stroke-width: 2; }
.status-chip b { font-weight: 700; color: #fff; font-size: 10px; }
.status-tip {
  position: absolute;
  z-index: 80;
  bottom: calc(100% + 8px);
  left: 50%;
  width: 168px;
  transform: translate(-50%, 4px);
  padding: 7px 9px;
  border-radius: 8px;
  border: 1px solid var(--line-strong);
  background: #0d131e;
  color: var(--muted);
  font-size: 10px;
  font-weight: 400;
  line-height: 1.4;
  text-align: center;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: 0.15s ease;
  box-shadow: 0 10px 24px rgba(0, 0, 0, 0.45);
}
.status-tip strong { display: block; font-size: 10px; letter-spacing: 0.08em; text-transform: uppercase; color: var(--c); margin-bottom: 2px; }
.status-chip:hover .status-tip,
.status-chip:focus-visible .status-tip { opacity: 1; visibility: visible; transform: translate(-50%, 0); }

/* ------------------------------------------------------------ element chip */

.el-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 8px 2px 5px;
  border-radius: 20px;
  border: 1px solid color-mix(in srgb, var(--c) 38%, transparent);
  background: color-mix(in srgb, var(--c) 10%, transparent);
  color: var(--c);
  font-size: 9.5px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  white-space: nowrap;
}
.el-chip .ico { width: 11px; height: 11px; }
.el-chip.small { font-size: 8.5px; padding: 1px 6px 1px 4px; }
.el-chip.small .ico { width: 9px; height: 9px; }

/* ---------------------------------------------------------------- charms */

.charm-chip {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 10px 6px 6px;
  border-radius: 9px;
  border: 1px solid color-mix(in srgb, var(--c) 28%, var(--line));
  background: linear-gradient(160deg, color-mix(in srgb, var(--c) 10%, rgba(255, 255, 255, 0.02)), rgba(255, 255, 255, 0.01));
  text-align: left;
}
.charm-chip.actionable { cursor: pointer; width: 100%; }
.charm-chip.actionable:hover { border-color: color-mix(in srgb, var(--c) 55%, transparent); }
.charm-ic {
  display: grid;
  place-items: center;
  width: 27px;
  height: 27px;
  flex: none;
  border-radius: 7px;
  color: var(--c);
  background: color-mix(in srgb, var(--c) 13%, #0b1018);
  border: 1px solid color-mix(in srgb, var(--c) 30%, transparent);
  box-shadow: inset 0 0 10px color-mix(in srgb, var(--c) 15%, transparent);
}
.charm-ic .ico { width: 15px; height: 15px; }
.charm-txt { display: flex; flex-direction: column; min-width: 0; gap: 1px; }
.charm-txt b { font-size: 11px; font-weight: 600; color: var(--text); line-height: 1.2; }
.charm-txt i { font-style: normal; font-size: 9px; line-height: 1.35; color: var(--dim); }
.charm-price { margin-left: auto; padding-left: 6px; color: var(--gold); font-size: 11px; font-weight: 600; }

.charm-tile {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 5px;
  width: 100%;
  padding: 22px 16px 18px;
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--c) 30%, var(--line));
  background:
    radial-gradient(circle at 50% 22%, color-mix(in srgb, var(--c) 17%, transparent), transparent 58%),
    linear-gradient(170deg, rgba(255, 255, 255, 0.035), rgba(255, 255, 255, 0.005));
  color: var(--text);
  cursor: pointer;
  overflow: hidden;
  transition: 0.2s ease;
}
.charm-tile::before {
  content: '';
  position: absolute;
  inset: 4px;
  border-radius: 10px;
  border: 1px solid color-mix(in srgb, var(--c) 14%, transparent);
  pointer-events: none;
}
.charm-tile:hover:not(:disabled) { transform: translateY(-4px); border-color: color-mix(in srgb, var(--c) 60%, transparent); }
.charm-tile:disabled { opacity: 0.45; cursor: not-allowed; }
.charm-halo {
  position: absolute;
  top: 10px;
  width: 88px;
  height: 88px;
  border-radius: 50%;
  border: 1px solid color-mix(in srgb, var(--c) 26%, transparent);
  box-shadow: 0 0 30px color-mix(in srgb, var(--c) 12%, transparent), inset 0 0 24px color-mix(in srgb, var(--c) 10%, transparent);
}
.charm-halo::before, .charm-halo::after {
  content: '';
  position: absolute;
  inset: 8px;
  border-radius: 50%;
  border: 1px solid color-mix(in srgb, var(--c) 18%, transparent);
}
.charm-halo::after { inset: 18px; border-style: dashed; opacity: 0.6; }
.charm-big {
  position: relative;
  display: grid;
  place-items: center;
  width: 66px;
  height: 66px;
  border-radius: 50%;
  color: var(--c);
  background: radial-gradient(circle at 40% 32%, color-mix(in srgb, var(--c) 25%, #141b28), #0b1018 72%);
  border: 1px solid color-mix(in srgb, var(--c) 40%, transparent);
  box-shadow: 0 0 22px color-mix(in srgb, var(--c) 16%, transparent);
  margin-bottom: 8px;
}
.charm-big .ico { width: 32px; height: 32px; stroke-width: 1.4; filter: drop-shadow(0 0 8px color-mix(in srgb, var(--c) 50%, transparent)); }
.charm-name { position: relative; font-family: var(--serif); font-size: 15px; font-weight: 700; color: #fbf2df; }
.charm-desc { position: relative; font-size: 11.5px; line-height: 1.45; color: var(--muted); max-width: 210px; }
.charm-flavor { position: relative; font-size: 10px; font-style: italic; color: var(--dim); margin-top: 3px; }
.price-tag, .free-tag {
  position: relative;
  margin-top: 7px;
  padding: 2px 9px;
  border-radius: 20px;
  font-size: 9.5px;
  font-weight: 600;
  letter-spacing: 0.08em;
}
.price-tag { color: var(--gold); background: rgba(242, 193, 121, 0.09); border: 1px solid rgba(242, 193, 121, 0.22); }
.free-tag { color: var(--rose); background: rgba(255, 159, 196, 0.08); border: 1px solid rgba(255, 159, 196, 0.22); }

/* ------------------------------------------------------------ species tile */

.species-tile {
  display: flex;
  flex-direction: column;
  border-radius: 12px;
  border: 1px solid var(--line);
  background: linear-gradient(170deg, rgba(255, 255, 255, 0.035), rgba(255, 255, 255, 0.008));
  overflow: hidden;
}
.species-tile.locked { opacity: 0.42; filter: saturate(0.2); }
.species-art {
  height: 110px;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  padding: 8px 8px 0;
  background: radial-gradient(circle at 50% 65%, rgba(255, 225, 160, 0.09), transparent 60%);
}
.species-art .art-svg { height: 100%; width: auto; }
.species-info { padding: 8px 10px 10px; display: flex; flex-direction: column; gap: 3px; align-items: flex-start; }
.species-name { font-family: var(--serif); font-size: 13px; font-weight: 700; color: var(--text); }
.species-sub { font-size: 9.5px; font-style: italic; color: var(--dim); }
.species-trait { font-size: 9px; line-height: 1.4; color: var(--muted); }
.species-trait b { display: block; color: var(--gold); font-weight: 600; font-size: 9px; }
.species-count { font-size: 8.5px; color: var(--teal); letter-spacing: 0.05em; }

.mini-kin { display: flex; align-items: flex-end; justify-content: center; }
.mini-kin .art-svg { height: 100%; width: auto; }

/* ==========================================================================
   WILDBOUND — the Ember Road map
   ========================================================================== */

.map-screen {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 328px;
  gap: clamp(16px, 2.2vw, 30px);
  width: min(1420px, 100%);
  min-height: 100%;
  margin: 0 auto;
  padding: clamp(16px, 2.2vw, 28px) clamp(14px, 3vw, 36px) clamp(20px, 3vw, 36px);
  align-items: start;
}

.map-panel {
  position: relative;
  display: flex;
  flex-direction: column;
  min-width: 0;
  padding: clamp(16px, 2vw, 24px);
  border-radius: 18px;
  border: 1px solid var(--line);
  background:
    radial-gradient(90% 50% at 50% 0%, rgba(242, 193, 121, 0.035), transparent 60%),
    linear-gradient(180deg, rgba(18, 26, 40, 0.84), rgba(11, 16, 26, 0.88));
  box-shadow: var(--shadow), inset 0 1px 0 rgba(255, 255, 255, 0.04);
  overflow: hidden;
}
.map-panel::before {
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0.4;
  background-image:
    radial-gradient(1px 1px at 18% 22%, rgba(255, 240, 208, 0.3), transparent 60%),
    radial-gradient(1px 1px at 72% 61%, rgba(255, 240, 208, 0.18), transparent 60%),
    radial-gradient(1px 1px at 44% 84%, rgba(255, 240, 208, 0.16), transparent 60%);
  background-size: 230px 190px, 310px 270px, 270px 230px;
}
.map-head {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
  padding-bottom: 14px;
  border-bottom: 1px solid var(--line);
}
.map-head h1 { margin-top: 4px; }
.map-head p {
  margin-top: 6px;
  max-width: 420px;
  font-size: 12.5px;
  line-height: 1.5;
  color: var(--dim);
}
.map-progress {
  display: flex;
  align-items: baseline;
  gap: 3px;
  flex: none;
  padding-top: 4px;
  font-family: var(--serif);
  color: var(--gold);
}
.map-progress b { font-size: 30px; line-height: 1; font-weight: 700; }
.map-progress span { font-size: 13px; color: var(--dim); }
.map-progress i {
  display: block;
  margin-left: 8px;
  font-family: var(--sans);
  font-size: 8px;
  font-style: normal;
  font-weight: 700;
  letter-spacing: 0.2em;
  color: var(--dim);
  align-self: center;
}

.map-scroll {
  position: relative;
  z-index: 2;
  height: calc(100vh - var(--topbar) - 200px);
  height: calc(100dvh - var(--topbar) - 200px);
  min-height: 430px;
  max-height: 1040px;
  overflow-y: auto;
  overflow-x: hidden;
  padding: 18px 2px 8px;
  scrollbar-gutter: stable;
  mask-image: linear-gradient(180deg, transparent 0, #000 20px, #000 calc(100% - 26px), transparent 100%);
  -webkit-mask-image: linear-gradient(180deg, transparent 0, #000 20px, #000 calc(100% - 26px), transparent 100%);
}
.map-canvas {
  position: relative;
  min-width: 0;
  padding: 8px 0 22px;
}
.map-edges {
  position: absolute;
  inset: 0;
  z-index: 0;
  width: 100%;
  height: 100%;
  overflow: visible;
  pointer-events: none;
}
.map-edges .edge {
  fill: none;
  stroke: rgba(255, 235, 200, 0.12);
  stroke-width: 1.5;
  stroke-linecap: round;
  stroke-dasharray: 3 7;
}
.map-edges .edge.walked {
  stroke: rgba(242, 193, 121, 0.52);
  stroke-width: 2;
  stroke-dasharray: none;
  filter: drop-shadow(0 0 4px rgba(242, 193, 121, 0.35));
}
.map-edges .edge.next {
  stroke: rgba(255, 224, 160, 0.65);
  stroke-width: 2;
  stroke-dasharray: 2 6;
  animation: edgeFlow 1.2s linear infinite;
}
@keyframes edgeFlow { to { stroke-dashoffset: -8; } }

.map-rows { position: relative; z-index: 1; }
.map-row {
  position: relative;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  align-items: center;
  min-height: 106px;
  padding-left: 34px;
}
.map-row.single, .map-row.boss-row { grid-template-columns: 1fr; }
.map-row:not(.boss-row)::after {
  content: '';
  position: absolute;
  left: 34px;
  right: 0;
  bottom: 0;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(255, 235, 200, 0.055) 20%, rgba(255, 235, 200, 0.055) 80%, transparent);
}
.map-row.boss-row { min-height: 138px; padding-top: 10px; }
.map-row.boss-row::before {
  content: '';
  position: absolute;
  left: 50%;
  bottom: 50%;
  width: 190px;
  height: 190px;
  transform: translate(-50%, 50%);
  border-radius: 50%;
  background: radial-gradient(circle, rgba(255, 220, 140, 0.09), transparent 66%);
  pointer-events: none;
}
.floor-tag {
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
  font-family: var(--serif);
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.08em;
  color: #5f5a53;
  font-variant-numeric: tabular-nums;
}
.boss-row .floor-tag { color: var(--gold-deep); font-size: 7.5px; letter-spacing: 0.18em; }

.map-slot { display: flex; justify-content: center; align-items: center; }
.map-node {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  width: 132px;
  padding: 6px 4px;
  border: 0;
  background: none;
  color: var(--node, #ff9d6b);
  cursor: pointer;
  opacity: 0.36;
  filter: saturate(0.45);
  transition: opacity 0.25s ease, filter 0.25s ease, transform 0.2s ease;
}
.map-node:hover { transform: translateY(-2px); }
.map-node.available {
  opacity: 1;
  filter: none;
}
.map-node.visited { opacity: 0.5; filter: saturate(0.55); }
.map-node.visited:hover { opacity: 0.7; }
.map-node:not(.available):not(.visited) { cursor: default; }
.map-node.type-battle { --node: #ff9d6b; }
.map-node.type-catch { --node: #ff9fc4; }
.map-node.type-elite { --node: #ff6f7d; }
.map-node.type-shop { --node: #e9b95f; }
.map-node.type-rest { --node: #ffca6b; }
.map-node.type-boss { --node: #ffe39a; }

.node-disc {
  position: relative;
  z-index: 2;
  display: grid;
  place-items: center;
  width: 55px;
  height: 55px;
  border-radius: 50%;
  border: 1.5px solid color-mix(in srgb, var(--node) 38%, #2c3442);
  background:
    radial-gradient(circle at 40% 30%, color-mix(in srgb, var(--node) 22%, #1b2331), #0d131d 72%);
  color: var(--node);
  box-shadow:
    0 8px 18px rgba(0, 0, 0, 0.42),
    inset 0 1px 0 rgba(255, 255, 255, 0.1),
    inset 0 -8px 16px rgba(0, 0, 0, 0.3);
  transition: 0.22s ease;
}
.node-disc .ico { width: 23px; height: 23px; stroke-width: 1.5; filter: drop-shadow(0 0 6px color-mix(in srgb, var(--node) 35%, transparent)); }
.map-node.available .node-disc {
  border-color: color-mix(in srgb, var(--node) 72%, #fff);
  background:
    radial-gradient(circle at 40% 30%, color-mix(in srgb, var(--node) 40%, #1b2331), #0d131d 74%);
  box-shadow:
    0 0 0 4px color-mix(in srgb, var(--node) 9%, transparent),
    0 0 22px color-mix(in srgb, var(--node) 34%, transparent),
    0 8px 18px rgba(0, 0, 0, 0.4),
    inset 0 1px 0 rgba(255, 255, 255, 0.2);
}
.map-node.available:hover .node-disc {
  transform: scale(1.09);
  box-shadow:
    0 0 0 5px color-mix(in srgb, var(--node) 12%, transparent),
    0 0 30px color-mix(in srgb, var(--node) 48%, transparent),
    0 10px 22px rgba(0, 0, 0, 0.42),
    inset 0 1px 0 rgba(255, 255, 255, 0.24);
}
.node-pulse {
  position: absolute;
  z-index: 1;
  top: 0;
  left: 50%;
  width: 55px;
  height: 55px;
  margin-left: -27.5px;
  border-radius: 50%;
  border: 1.5px solid color-mix(in srgb, var(--node) 50%, transparent);
  opacity: 0;
  pointer-events: none;
}
.map-node.available .node-pulse { animation: nodePulse 2.4s ease-out infinite; }
@keyframes nodePulse {
  0% { opacity: 0.7; transform: scale(1); }
  75%, 100% { opacity: 0; transform: scale(1.48); }
}
.node-name {
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--node);
  opacity: 0.8;
  white-space: nowrap;
}
.node-tip {
  position: absolute;
  z-index: 20;
  top: 58px;
  left: 50%;
  width: 178px;
  transform: translate(-50%, 4px);
  padding: 6px 8px;
  border-radius: 7px;
  background: #0c121c;
  border: 1px solid var(--line-strong);
  color: var(--muted);
  font-size: 10px;
  line-height: 1.4;
  text-align: center;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: 0.16s ease;
  box-shadow: 0 8px 22px rgba(0, 0, 0, 0.45);
}
.map-node.available:hover .node-tip,
.map-node:focus-visible .node-tip { opacity: 1; visibility: visible; transform: translate(-50%, 0); }
.node-check {
  position: absolute;
  z-index: 3;
  top: 4px;
  right: 26px;
  display: grid;
  place-items: center;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: #1b2a2c;
  border: 1px solid rgba(127, 216, 210, 0.4);
  color: var(--teal);
}
.node-check .ico { width: 9px; height: 9px; stroke-width: 2.5; }

.map-node.boss-node { width: 160px; }
.map-node.boss-node .node-disc {
  width: 80px;
  height: 80px;
  border-width: 2px;
  border-color: rgba(255, 227, 154, 0.55);
  background: radial-gradient(circle at 42% 32%, #5a4725, #181710 72%);
  box-shadow: 0 0 0 6px rgba(255, 227, 154, 0.05), 0 0 40px rgba(255, 219, 130, 0.18), 0 12px 26px rgba(0, 0, 0, 0.5), inset 0 1px 0 rgba(255, 255, 255, 0.16);
}
.map-node.boss-node .node-disc .ico { width: 34px; height: 34px; }
.map-node.boss-node.available .node-disc { animation: bossGlow 3.6s ease-in-out infinite; }
@keyframes bossGlow {
  0%, 100% { box-shadow: 0 0 0 6px rgba(255, 227, 154, 0.05), 0 0 32px rgba(255, 219, 130, 0.18), 0 12px 26px rgba(0, 0, 0, 0.5), inset 0 1px 0 rgba(255, 255, 255, 0.16); }
  50% { box-shadow: 0 0 0 10px rgba(255, 227, 154, 0.08), 0 0 56px rgba(255, 219, 130, 0.32), 0 12px 26px rgba(0, 0, 0, 0.5), inset 0 1px 0 rgba(255, 255, 255, 0.2); }
}
.map-node.boss-node .node-pulse { width: 80px; height: 80px; margin-left: -40px; }
.map-node.boss-node .node-name { font-family: var(--serif); font-size: 10px; letter-spacing: 0.18em; }

/* ------------------------------------------------------------------ side */

.map-side {
  display: flex;
  flex-direction: column;
  gap: 12px;
  min-width: 0;
}
.side-card {
  position: relative;
  padding: 14px;
  border-radius: 14px;
  border: 1px solid var(--line);
  background: linear-gradient(165deg, rgba(20, 28, 43, 0.8), rgba(11, 16, 25, 0.82));
  box-shadow: 0 14px 30px rgba(0, 0, 0, 0.24), inset 0 1px 0 rgba(255, 255, 255, 0.035);
  overflow: hidden;
}
.warden-card { display: flex; gap: 12px; align-items: center; padding: 12px 14px 13px; }
.warden-card::after {
  content: '';
  position: absolute;
  right: -30px;
  top: -40px;
  width: 150px;
  height: 150px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(242, 176, 92, 0.09), transparent 66%);
  pointer-events: none;
}
.warden-figure { width: 66px; flex: none; opacity: 0.95; filter: drop-shadow(0 8px 12px rgba(0, 0, 0, 0.4)); }
.warden-info { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 5px; }
.warden-info .eyebrow { font-size: 7.5px; letter-spacing: 0.2em; }
.warden-name { font-family: var(--serif); font-size: 12.5px; color: #f4e8d1; line-height: 1.2; }
.warden-info .hpbar { margin-top: 1px; }
.warden-stats { display: flex; gap: 12px; flex-wrap: wrap; margin-top: 1px; font-size: 10px; color: var(--dim); }
.warden-stats span { display: inline-flex; align-items: center; gap: 4px; }
.warden-stats .ico { color: var(--gold); width: 11px; height: 11px; }
.side-title {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.2em;
  color: var(--muted);
}
.side-title .ico { color: var(--gold); width: 13px; height: 13px; }
.side-title b { margin-left: auto; font-size: 11px; color: var(--gold-bright); letter-spacing: 0; }
.deck-breakdown { display: flex; flex-wrap: wrap; gap: 8px 14px; margin: 10px 0 8px; font-size: 10.5px; color: var(--dim); }
.deck-breakdown span { display: inline-flex; align-items: center; gap: 5px; }
.sword-dot, .skill-dot, .bond-dot { width: 6px; height: 6px; border-radius: 50%; flex: none; }
.sword-dot { background: #ff9d6b; box-shadow: 0 0 6px #ff9d6b66; }
.skill-dot { background: #7fd8d2; box-shadow: 0 0 6px #7fd8d266; }
.bond-dot { background: #ff9fc4; box-shadow: 0 0 6px #ff9fc466; }
.side-charms { display: flex; flex-direction: column; gap: 6px; margin-top: 9px; }
.legend-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 5px 8px;
  margin-top: 9px;
}
.legend-grid span {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 9.5px;
  color: var(--dim);
}
.legend-grid .ico { width: 12px; height: 12px; color: var(--gold-deep); }
.legend-card { padding-bottom: 12px; }

/* ------------------------------------------------------------- map loader */

.map-screen { animation: riseIn 0.55s ease both; }
.side-card { animation: riseIn 0.55s ease both; }
.side-card:nth-child(2) { animation-delay: 0.04s; }
.side-card:nth-child(3) { animation-delay: 0.08s; }
.side-card:nth-child(4) { animation-delay: 0.12s; }

/* ==========================================================================
   WILDBOUND — combat arena
   ========================================================================== */

body[data-screen='combat'] .screen { overflow: hidden; }

.combat-screen {
  position: relative;
  height: calc(100vh - var(--topbar));
  height: calc(100dvh - var(--topbar) - env(safe-area-inset-top, 0px));
  display: flex;
  flex-direction: column;
  min-height: 0;
  animation: combatIn 0.45s ease both;
}
@keyframes combatIn { from { opacity: 0; } to { opacity: 1; } }

.arena {
  position: relative;
  flex: 1 1 auto;
  min-height: 0;
  overflow: hidden;
  background:
    radial-gradient(90% 70% at 76% 8%, rgba(53, 63, 79, 0.5) 0%, transparent 58%),
    radial-gradient(120% 90% at 50% -10%, #152234 0%, #0b1420 46%, #070b12 100%);
  isolation: isolate;
}
.arena-sky {
  position: absolute;
  inset: 0;
  z-index: 0;
  background:
    radial-gradient(42% 30% at 74% 12%, rgba(116, 137, 167, 0.1), transparent 70%),
    radial-gradient(60% 42% at 22% 26%, rgba(89, 112, 141, 0.07), transparent 70%);
}
.arena-sky::before {
  content: '';
  position: absolute;
  inset: 0;
  opacity: 0.55;
  background-image:
    radial-gradient(1px 1px at 18% 22%, rgba(255, 244, 214, 0.5), transparent 60%),
    radial-gradient(1px 1px at 63% 18%, rgba(255, 244, 214, 0.32), transparent 60%),
    radial-gradient(1.3px 1.3px at 88% 36%, rgba(255, 244, 214, 0.4), transparent 60%),
    radial-gradient(1px 1px at 38% 48%, rgba(255, 244, 214, 0.22), transparent 60%);
  background-size: 310px 250px, 420px 330px, 280px 230px, 360px 290px;
}
.arena-moon {
  position: absolute;
  z-index: 0;
  top: 2%;
  left: 4%;
  width: clamp(110px, 15vw, 210px);
  opacity: 0.42;
  filter: drop-shadow(0 0 36px rgba(255, 232, 176, 0.15));
  pointer-events: none;
}
.arena-mist {
  position: absolute;
  z-index: 0;
  left: -10%;
  right: -10%;
  height: 90px;
  background: radial-gradient(ellipse at center, rgba(155, 183, 205, 0.09), transparent 68%);
  filter: blur(18px);
  pointer-events: none;
}
.arena-mist.m1 { top: 41%; animation: mistDrift 30s ease-in-out infinite; }
.arena-mist.m2 { top: 58%; opacity: 0.7; animation: mistDrift 42s ease-in-out infinite reverse; }
@keyframes mistDrift {
  0%, 100% { transform: translateX(-3%); }
  50% { transform: translateX(4%); }
}
.arena-ground {
  position: absolute;
  z-index: 0;
  left: 0;
  right: 0;
  bottom: 0;
  height: 38%;
  background:
    radial-gradient(70% 100% at 50% 0%, rgba(31, 45, 56, 0.7), transparent 72%),
    linear-gradient(180deg, transparent 0%, #0a1118 30%, #06090e 100%);
}
.arena-ground::before {
  content: '';
  position: absolute;
  left: 0;
  right: 0;
  top: 18%;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(127, 216, 210, 0.09) 30%, rgba(242, 193, 121, 0.09) 70%, transparent);
}
.arena .firefly { z-index: 1; opacity: 0.6; }

.arena-topline {
  position: absolute;
  z-index: 8;
  top: 14px;
  left: clamp(12px, 2.4vw, 30px);
  right: clamp(12px, 2.4vw, 30px);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  pointer-events: none;
}
.turn-pill {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 5px 12px;
  border-radius: 20px;
  border: 1px solid rgba(255, 235, 200, 0.14);
  background: rgba(8, 12, 19, 0.55);
  backdrop-filter: blur(8px);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.2em;
  color: var(--gold-bright);
  text-shadow: 0 1px 4px #000;
}
.turn-pill i { color: var(--dim); font-style: normal; }
.combat-mode {
  font-family: var(--serif);
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.24em;
  color: rgba(242, 193, 121, 0.5);
  text-shadow: 0 1px 6px #000;
}

/* ------------------------------------------------------------- combatants */

.player-side {
  position: absolute;
  z-index: 5;
  left: clamp(14px, 6vw, 100px);
  bottom: clamp(12px, 4.2vh, 40px);
  width: clamp(150px, 21vw, 260px);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
}
.player-nameplate {
  text-align: center;
  margin-bottom: 1px;
  text-shadow: 0 2px 8px #000;
}
.player-nameplate .eyebrow { font-size: 7.5px; letter-spacing: 0.24em; opacity: 0.8; }
.player-nameplate b {
  display: block;
  font-family: var(--serif);
  font-size: clamp(12px, 1.4vw, 16px);
  letter-spacing: 0.1em;
  color: #f8ecd5;
  font-weight: 600;
}
.player-figure {
  position: relative;
  width: 100%;
  height: clamp(120px, 23vh, 218px);
  display: flex;
  align-items: flex-end;
  justify-content: center;
  filter: drop-shadow(0 20px 18px rgba(0, 0, 0, 0.5));
}
.player-figure::before {
  content: '';
  position: absolute;
  z-index: -1;
  left: 44%;
  bottom: 24%;
  width: 58%;
  aspect-ratio: 1;
  transform: translateX(-50%);
  border-radius: 50%;
  background: radial-gradient(circle, rgba(255, 217, 113, 0.2), transparent 65%);
  filter: blur(10px);
}
.player-figure .art-svg { height: 100%; width: auto; animation: floaty 6.5s ease-in-out infinite; }
.player-hp { width: 100%; max-width: 190px; }
.player-side .status-row { max-width: 200px; margin-top: 1px; }

.block-badge {
  position: absolute;
  z-index: 6;
  right: 4%;
  bottom: 13%;
  display: inline-flex;
  align-items: center;
  gap: 3px;
  padding: 3px 8px 3px 5px;
  border-radius: 20px;
  border: 1px solid rgba(143, 211, 255, 0.5);
  background: rgba(11, 26, 38, 0.92);
  color: #bde9ff;
  font-size: 11px;
  font-weight: 700;
  box-shadow: 0 0 16px rgba(120, 200, 255, 0.22), 0 4px 10px rgba(0, 0, 0, 0.4);
}
.block-badge .ico { width: 13px; height: 13px; }
.block-badge b { font-size: 11px; }

.enemy-side {
  position: absolute;
  z-index: 5;
  top: clamp(30px, 6.5vh, 58px);
  right: clamp(14px, 5vw, 84px);
  width: clamp(230px, 33vw, 390px);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
}
.intent-wrap {
  position: relative;
  z-index: 10;
  display: flex;
  align-items: flex-start;
  gap: 6px;
  margin-bottom: 4px;
}
.intent {
  display: flex;
  align-items: center;
  gap: 7px;
  max-width: 250px;
  padding: 5px 10px 5px 5px;
  border-radius: 24px;
  border: 1px solid rgba(255, 235, 200, 0.16);
  background: rgba(8, 12, 19, 0.76);
  backdrop-filter: blur(8px);
  box-shadow: 0 6px 16px rgba(0, 0, 0, 0.34);
  color: var(--text);
}
.intent-icon {
  display: grid;
  place-items: center;
  width: 26px;
  height: 26px;
  flex: none;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.1);
}
.intent-icon .ico { width: 14px; height: 14px; }
.intent-text { display: flex; flex-direction: column; min-width: 0; text-align: left; }
.intent-text b {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  line-height: 1.25;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.intent-text i { font-style: normal; font-size: 9px; line-height: 1.3; color: var(--muted); white-space: nowrap; }
.intent.attack { border-color: rgba(255, 125, 125, 0.36); }
.intent.attack .intent-icon { color: #ff9d94; border-color: rgba(255, 125, 125, 0.3); background: rgba(255, 100, 100, 0.09); }
.intent.defend .intent-icon { color: #9fdcff; border-color: rgba(143, 211, 255, 0.3); background: rgba(120, 200, 255, 0.08); }
.intent.buff .intent-icon { color: var(--gold); border-color: rgba(242, 193, 121, 0.3); background: rgba(242, 193, 121, 0.08); }
.intent.debuff .intent-icon { color: #d2b4ff; border-color: rgba(186, 140, 255, 0.3); background: rgba(160, 110, 255, 0.08); }
.intent.second { transform: scale(0.86); transform-origin: top left; opacity: 0.68; }

.enemy-nameplate { text-align: center; text-shadow: 0 2px 8px #000; }
.enemy-nameplate .eyebrow { font-size: 7px; letter-spacing: 0.24em; opacity: 0.72; }
.enemy-nameplate b {
  display: block;
  font-family: var(--serif);
  font-size: clamp(15px, 1.85vw, 22px);
  font-weight: 700;
  letter-spacing: 0.045em;
  line-height: 1.15;
  color: #fbf1dc;
}
.enemy-nameplate i {
  display: block;
  font-style: italic;
  font-size: 10px;
  color: var(--dim);
  margin-bottom: 3px;
}
.enemy-nameplate .el-chip { margin-bottom: 2px; }
.enemy-figure {
  position: relative;
  width: 100%;
  height: clamp(118px, 24vh, 226px);
  display: flex;
  align-items: flex-end;
  justify-content: center;
  filter: drop-shadow(0 24px 22px rgba(0, 0, 0, 0.48));
}
.enemy-figure::before {
  content: '';
  position: absolute;
  z-index: -1;
  left: 50%;
  bottom: 18%;
  width: 120%;
  height: 90%;
  transform: translateX(-50%);
  background: radial-gradient(ellipse at 50% 60%, rgba(242, 176, 92, 0.1), transparent 62%);
  filter: blur(8px);
}
.enemy-figure .art-svg { height: 100%; width: auto; animation: floaty 5.4s ease-in-out infinite; }
.enemy-hp { width: min(280px, 100%); }
.enemy-side .status-row { margin-top: 3px; max-width: 280px; }
.trait-line {
  display: flex;
  align-items: center;
  gap: 5px;
  max-width: 290px;
  margin-top: 2px;
  font-size: 9px;
  color: var(--dim);
  text-align: center;
  line-height: 1.35;
  cursor: help;
}
.trait-line b { color: var(--gold); font-weight: 600; font-size: 9px; white-space: nowrap; }
.trait-line span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; opacity: 0.8; }

.weakened-badge {
  position: absolute;
  z-index: 6;
  top: 2%;
  left: 50%;
  transform: translateX(-50%);
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 3px 9px;
  border-radius: 20px;
  border: 1px solid rgba(255, 159, 196, 0.5);
  background: rgba(40, 14, 28, 0.86);
  color: var(--rose);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.16em;
  box-shadow: 0 0 18px rgba(255, 130, 170, 0.25);
  animation: weakBreathe 2s ease-in-out infinite;
}
.weakened-badge .ico { width: 11px; height: 11px; }
@keyframes weakBreathe {
  0%, 100% { box-shadow: 0 0 12px rgba(255, 130, 170, 0.18); }
  50% { box-shadow: 0 0 24px rgba(255, 130, 170, 0.4); }
}

/* ------------------------------------------------------------ catch centre */

.arena-center {
  position: absolute;
  z-index: 7;
  left: 50%;
  bottom: clamp(42px, 10vh, 96px);
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  pointer-events: none;
}
.catch-hint {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 6px 13px;
  border-radius: 20px;
  border: 1px solid rgba(255, 159, 196, 0.15);
  background: rgba(8, 12, 19, 0.5);
  color: var(--dim);
  font-size: 10px;
  letter-spacing: 0.03em;
  backdrop-filter: blur(6px);
  white-space: nowrap;
}
.catch-hint .ico { color: var(--rose); width: 13px; height: 13px; opacity: 0.8; }
.catch-hint b { color: var(--rose); font-weight: 600; }

.catch-orb {
  position: relative;
  display: grid;
  place-items: center;
  width: clamp(66px, 8vw, 94px);
  height: clamp(66px, 8vw, 94px);
  border: 1px solid rgba(255, 159, 196, 0.36);
  border-radius: 50%;
  background:
    radial-gradient(circle at 42% 34%, rgba(255, 196, 216, 0.28), rgba(52, 18, 34, 0.9) 62%, #1a0b15 100%);
  color: var(--rose);
  cursor: pointer;
  pointer-events: auto;
  box-shadow:
    0 0 0 6px rgba(255, 159, 196, 0.04),
    0 0 30px rgba(255, 120, 165, 0.18),
    inset 0 1px 0 rgba(255, 255, 255, 0.16);
  transition: 0.2s ease;
}
.catch-orb .orb-core { display: grid; place-items: center; width: 46%; height: 46%; }
.catch-orb .orb-core .ico { width: 100%; height: 100%; stroke-width: 1.4; filter: drop-shadow(0 0 8px rgba(255, 159, 196, 0.5)); }
.orb-ring {
  position: absolute;
  inset: -5px;
  border-radius: 50%;
  border: 1px solid rgba(255, 159, 196, 0.25);
  opacity: 0.6;
}
.catch-orb.ready {
  border-color: rgba(255, 196, 216, 0.8);
  color: #ffd6e4;
  animation: orbReady 2s ease-in-out infinite;
}
.catch-orb.ready .orb-ring { animation: orbRing 1.9s ease-out infinite; }
.catch-orb.ready:hover { transform: scale(1.06); }
.catch-orb:disabled { opacity: 0.5; cursor: not-allowed; }
.catch-orb .orb-label {
  position: absolute;
  top: calc(100% + 7px);
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.16em;
  color: var(--rose);
  white-space: nowrap;
  text-shadow: 0 1px 4px #000;
}
.catch-orb .orb-label i { font-style: normal; font-size: 7px; letter-spacing: 0.08em; color: var(--dim); font-weight: 500; }
@keyframes orbReady {
  0%, 100% { box-shadow: 0 0 0 6px rgba(255, 159, 196, 0.05), 0 0 26px rgba(255, 120, 165, 0.18), inset 0 1px 0 rgba(255, 255, 255, 0.16); }
  50% { box-shadow: 0 0 0 10px rgba(255, 159, 196, 0.08), 0 0 48px rgba(255, 120, 165, 0.38), inset 0 1px 0 rgba(255, 255, 255, 0.22); }
}
@keyframes orbRing {
  0% { transform: scale(0.9); opacity: 0.7; }
  100% { transform: scale(1.35); opacity: 0; }
}

.combat-log {
  position: absolute;
  z-index: 4;
  right: clamp(12px, 2.6vw, 34px);
  bottom: clamp(10px, 2.4vh, 22px);
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 2px;
  max-width: min(300px, 34vw);
  pointer-events: none;
  text-align: right;
}
.combat-log span {
  font-size: 10px;
  line-height: 1.35;
  color: rgba(176, 167, 152, 0.7);
  text-shadow: 0 1px 4px #000;
}
.combat-log span:first-child { color: rgba(241, 233, 219, 0.9); }

.combat-hint {
  position: absolute;
  z-index: 40;
  top: 54px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 10px;
  width: min(680px, calc(100% - 24px));
  padding: 10px 12px 10px 14px;
  border-radius: 10px;
  border: 1px solid rgba(242, 193, 121, 0.24);
  background: rgba(12, 18, 29, 0.94);
  backdrop-filter: blur(12px);
  font-size: 11.5px;
  line-height: 1.45;
  color: var(--muted);
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.4);
  animation: hintIn 0.5s 0.3s ease both;
}
@keyframes hintIn { from { opacity: 0; transform: translate(-50%, -8px); } to { opacity: 1; transform: translate(-50%, 0); } }
.combat-hint > .ico { color: var(--gold); width: 16px; height: 16px; flex: none; }
.combat-hint b { color: var(--gold-bright); }
.combat-hint button {
  margin-left: auto;
  display: grid;
  place-items: center;
  width: 27px;
  height: 27px;
  flex: none;
  border: 1px solid var(--line);
  border-radius: 7px;
  background: transparent;
  color: var(--dim);
  cursor: pointer;
}
.combat-hint button .ico { width: 12px; height: 12px; }

/* --------------------------------------------------------------- the hand */

.combat-bottom {
  position: relative;
  z-index: 12;
  flex: 0 0 auto;
  height: clamp(214px, 27vh, 262px);
  padding: 4px clamp(8px, 1.6vw, 22px) calc(8px + env(safe-area-inset-bottom, 0px));
  background:
    linear-gradient(180deg, rgba(8, 11, 18, 0) 0%, rgba(8, 11, 18, 0.7) 18%, #080b12 52%);
  border-top: 1px solid rgba(255, 235, 200, 0.06);
}
.hand-zone {
  display: grid;
  grid-template-columns: auto auto minmax(0, 1fr) auto;
  align-items: center;
  gap: clamp(4px, 1vw, 14px);
  height: 100%;
}
.pile {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1px;
  width: 54px;
  padding: 7px 3px;
  border-radius: 9px;
  border: 1px solid var(--line);
  background: linear-gradient(165deg, rgba(255, 255, 255, 0.035), rgba(255, 255, 255, 0.008));
  color: var(--dim);
}
.pile .ico { width: 17px; height: 17px; color: var(--gold-deep); opacity: 0.85; }
.pile b { font-size: 13px; font-weight: 600; color: var(--text); line-height: 1; }
.pile span { font-size: 6.5px; font-weight: 700; letter-spacing: 0.14em; color: var(--dim); }
.exhaust-pile { border-color: rgba(255, 125, 125, 0.16); }
.exhaust-pile .ico { color: #ff8b7b; }

.energy-orb {
  position: relative;
  display: grid;
  place-items: center;
  width: clamp(62px, 6.4vw, 84px);
  height: clamp(62px, 6.4vw, 84px);
  border-radius: 50%;
  border: 1px solid rgba(242, 193, 121, 0.4);
  background: radial-gradient(circle at 40% 32%, #4a3a24, #191720 55%, #0b0e15 100%);
  color: var(--gold-bright);
  box-shadow: 0 0 24px rgba(242, 193, 121, 0.15), inset 0 1px 0 rgba(255, 255, 255, 0.13);
  flex: none;
}
.energy-orb .energy-ring {
  position: absolute;
  inset: 4px;
  border-radius: 50%;
  border: 1px solid rgba(242, 193, 121, 0.18);
}
.energy-orb b {
  font-family: var(--serif);
  font-size: clamp(20px, 2.4vw, 29px);
  line-height: 1;
  font-weight: 700;
  text-shadow: 0 0 14px rgba(242, 193, 121, 0.4);
}
.energy-orb i { position: absolute; top: 50%; left: calc(50% + 11px); transform: translateY(-50%); font-style: normal; font-size: 9px; color: var(--dim); }
.energy-orb > span:last-of-type {
  position: absolute;
  bottom: -13px;
  font-size: 6.5px;
  font-weight: 700;
  letter-spacing: 0.16em;
  color: var(--dim);
}
.energy-orb em {
  position: absolute;
  top: calc(100% + 1px);
  font-style: normal;
  font-size: 6.5px;
  letter-spacing: 0.03em;
  color: var(--teal);
  white-space: nowrap;
}
.energy-orb.empty { filter: saturate(0.4) brightness(0.8); }

.hand {
  --card-w: clamp(88px, 9.8vw, 144px);
  display: flex;
  align-items: flex-end;
  justify-content: center;
  height: 100%;
  min-width: 0;
  padding: 24px 4px 8px;
}
.hand-slot {
  position: relative;
  flex: 0 0 auto;
  width: var(--card-w);
  transform: rotate(var(--rot, 0deg)) translateY(var(--lift, 0px));
  transform-origin: 50% 100%;
  transition: transform 0.18s ease;
}
.hand-slot + .hand-slot { margin-left: clamp(1px, 0.35vw, 7px); }
.hand.many { --card-w: clamp(92px, 10.4vw, 150px); }
.hand.many .hand-slot + .hand-slot { margin-left: calc(var(--card-w) * -0.54); }
.hand-slot .card { width: 100%; }
.hand-slot:hover { z-index: 30 !important; }
.hand-slot:hover .card { transform: translateY(-16px) scale(1.06); }
.empty-hand {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  color: var(--dim);
  font-size: 11px;
  letter-spacing: 0.04em;
}
.empty-hand .ico { width: 24px; height: 24px; color: var(--gold-deep); opacity: 0.6; }

.turn-controls { display: flex; align-items: center; gap: 8px; }
.end-turn {
  flex-direction: column;
  gap: 2px;
  min-width: clamp(82px, 9vw, 118px);
  min-height: 62px;
  padding: 8px 12px;
  border-color: rgba(255, 228, 173, 0.45);
  background: linear-gradient(180deg, #2b2419, #14131a);
  color: var(--gold-bright);
}
.end-turn span { font-size: 11.5px; font-weight: 600; letter-spacing: 0.05em; }
.end-turn kbd { color: var(--dim); border-color: rgba(255, 255, 255, 0.1); background: rgba(255, 255, 255, 0.04); }
.end-turn:hover:not(:disabled) { border-color: var(--gold); background: linear-gradient(180deg, #3a3020, #18161d); }
.discard-pile { width: 46px; padding: 5px 3px; }
.discard-pile .ico, .exhaust-pile .ico { width: 14px; height: 14px; }
.discard-pile b, .exhaust-pile b { font-size: 11px; }
.turn-controls .exhaust-pile { width: 40px; }

/* --------------------------------------------------------------- responsive tweaks inside combat */

@media (max-width: 1100px) {
  .enemy-side { width: clamp(210px, 34vw, 330px); }
  .player-side { width: clamp(140px, 19vw, 210px); }
  .combat-log { max-width: 220px; }
}

/* ==========================================================================
   WILDBOUND — results, catch, sigils, shop, camp, glade
   ========================================================================== */

.result-screen {
  position: relative;
  width: min(1140px, 100%);
  min-height: 100%;
  margin: 0 auto;
  padding: clamp(22px, 4vh, 46px) clamp(16px, 3.4vw, 40px) clamp(30px, 5vh, 56px);
  display: flex;
  flex-direction: column;
  align-items: center;
  animation: riseIn 0.5s ease both;
}
.result-head { max-width: 640px; text-align: center; }
.result-head h1 { margin-top: 8px; }
.result-head p { margin-top: 10px; font-size: 13px; line-height: 1.6; color: var(--dim); }
.result-hero {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: clamp(10px, 3vw, 38px);
  margin: 20px 0 8px;
}
.result-kin { width: clamp(120px, 15vw, 180px); filter: drop-shadow(0 16px 20px rgba(0, 0, 0, 0.4)); }
.result-summary { display: flex; flex-direction: column; gap: 6px; }
.reward-gold {
  display: flex;
  align-items: baseline;
  gap: 5px;
  font-family: var(--serif);
  color: var(--gold-bright);
}
.reward-gold .ico { width: 19px; height: 19px; color: var(--gold); align-self: center; }
.reward-gold b { font-size: 30px; line-height: 1; }
.reward-gold span { font-size: 10px; letter-spacing: 0.14em; text-transform: uppercase; color: var(--dim); font-family: var(--sans); }
.result-note { max-width: 290px; font-size: 11px; line-height: 1.5; color: var(--dim); }
.reward-heading {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  margin: 18px 0 14px;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.22em;
  color: var(--gold);
}
.reward-heading i { font-style: italic; font-size: 10px; letter-spacing: 0.03em; color: var(--dim); font-weight: 400; }
.reward-heading::before, .reward-heading::after {
  content: '';
  width: min(90px, 12vw);
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(242, 193, 121, 0.3));
}
.reward-heading::after { background: linear-gradient(90deg, rgba(242, 193, 121, 0.3), transparent); }

.card-offer {
  display: flex;
  align-items: stretch;
  justify-content: center;
  gap: clamp(8px, 1.5vw, 18px);
  width: 100%;
  padding: 6px 4px 14px;
}
.card-offer .card, .single-card-offer .card { width: clamp(128px, 16.5vw, 196px); flex: none; }
.card-offer .card:hover { transform: translateY(-7px); }
.single-card-offer { display: flex; justify-content: center; padding: 4px 0 12px; }
.card-offer .card, .single-card-offer .card, .charm-tile { animation: riseIn 0.5s ease both; }
.card-offer > :nth-child(2) { animation-delay: 0.06s; }
.card-offer > :nth-child(3) { animation-delay: 0.12s; }
.result-actions { display: flex; justify-content: center; gap: 10px; flex-wrap: wrap; margin-top: 8px; }

/* ------------------------------------------------------------------ catch */

.catch-screen {
  justify-content: center;
  padding-top: clamp(18px, 3vh, 34px);
}
.catch-hero { position: relative; text-align: center; width: min(560px, 100%); }
.catch-rings {
  position: absolute;
  top: 46%;
  left: 50%;
  width: 280px;
  height: 280px;
  transform: translate(-50%, -50%);
  pointer-events: none;
  z-index: 0;
}
.catch-rings span {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  border: 1px solid rgba(255, 159, 196, 0.16);
  animation: catchRing 5s ease-in-out infinite;
}
.catch-rings span:nth-child(2) { inset: 26px; animation-delay: -1.6s; border-color: rgba(242, 193, 121, 0.12); }
.catch-rings span:nth-child(3) { inset: 54px; animation-delay: -3.2s; border-color: rgba(127, 216, 210, 0.1); }
@keyframes catchRing {
  0%, 100% { transform: scale(0.96); opacity: 0.45; }
  50% { transform: scale(1.03); opacity: 0.9; }
}
.catch-kin {
  position: relative;
  z-index: 1;
  width: clamp(130px, 17vw, 200px);
  margin: 0 auto -10px;
  filter: drop-shadow(0 20px 24px rgba(0, 0, 0, 0.45));
  animation: floaty 6s ease-in-out infinite;
}
.catch-badge {
  position: relative;
  z-index: 2;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  margin-bottom: 8px;
  padding: 3px 10px;
  border-radius: 20px;
  border: 1px solid rgba(255, 159, 196, 0.36);
  background: rgba(255, 159, 196, 0.07);
  color: var(--rose);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.18em;
}
.catch-badge .ico { width: 11px; height: 11px; }
.catch-hero h1 { margin-top: 2px; font-size: clamp(34px, 4.6vw, 54px); }
.catch-tags { display: flex; justify-content: center; align-items: center; gap: 7px; margin-top: 8px; flex-wrap: wrap; }
.trait-pill {
  display: inline-flex;
  align-items: center;
  padding: 2px 9px;
  border-radius: 20px;
  border: 1px solid rgba(242, 193, 121, 0.25);
  background: rgba(242, 193, 121, 0.06);
  color: var(--gold);
  font-size: 9px;
  letter-spacing: 0.04em;
}
.catch-lore {
  max-width: 480px;
  margin: 10px auto 0;
  font-size: 12px;
  line-height: 1.6;
  font-style: italic;
  color: var(--dim);
}
.catch-bonuses {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 6px 8px;
  margin: 16px 0 2px;
  max-width: 720px;
}
.catch-bonuses span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 10px;
  border-radius: 20px;
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.025);
  color: var(--muted);
  font-size: 10px;
}
.catch-bonuses .ico { width: 12px; height: 12px; color: var(--gold); }
.catch-screen .card-offer { margin-top: 2px; }

/* ----------------------------------------------------------------- charms */

.charm-screen { justify-content: center; text-align: center; }
.charm-offer {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: clamp(8px, 1.6vw, 18px);
  width: min(860px, 100%);
  margin: 24px 0 16px;
}
.charm-offer .charm-tile { animation: riseIn 0.5s ease both; }
.charm-offer .charm-tile:nth-child(2) { animation-delay: 0.06s; }
.charm-offer .charm-tile:nth-child(3) { animation-delay: 0.12s; }

/* ------------------------------------------------------------------- shop */

.shop-screen {
  width: min(1180px, 100%);
  margin: 0 auto;
  padding: clamp(18px, 3vh, 36px) clamp(14px, 3vw, 38px) clamp(30px, 5vh, 60px);
  animation: riseIn 0.5s ease both;
}
.shop-head {
  display: flex;
  align-items: center;
  gap: clamp(14px, 3vw, 34px);
  padding: clamp(16px, 2.4vw, 26px);
  border-radius: 18px;
  border: 1px solid var(--line);
  background:
    radial-gradient(70% 120% at 12% 40%, rgba(255, 190, 100, 0.07), transparent 60%),
    linear-gradient(165deg, rgba(25, 32, 46, 0.78), rgba(12, 17, 27, 0.82));
  box-shadow: var(--shadow), inset 0 1px 0 rgba(255, 255, 255, 0.04);
  overflow: hidden;
}
.shop-keeper {
  width: clamp(100px, 12vw, 160px);
  flex: none;
  filter: drop-shadow(0 14px 18px rgba(0, 0, 0, 0.45));
}
.shop-talk { min-width: 0; }
.shop-talk h1 { margin: 4px 0 6px; }
.shop-greeting { font-size: 13.5px; font-style: italic; line-height: 1.55; color: var(--muted); max-width: 640px; }
.shop-wallet {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-top: 10px;
  padding: 4px 12px;
  border-radius: 20px;
  border: 1px solid rgba(242, 193, 121, 0.24);
  background: rgba(242, 193, 121, 0.06);
  font-size: 11px;
  color: var(--dim);
}
.shop-wallet .ico { color: var(--gold); width: 14px; height: 14px; }
.shop-wallet b { color: var(--gold-bright); font-size: 14px; }

.shop-section { margin-top: clamp(20px, 3vh, 30px); }
.shop-section-head {
  display: flex;
  align-items: baseline;
  gap: 10px;
  margin-bottom: 12px;
  padding-bottom: 8px;
  border-bottom: 1px solid var(--line);
}
.shop-section-head h2 {
  display: flex;
  align-items: center;
  gap: 7px;
  font-family: var(--serif);
  font-size: 16px;
  font-weight: 600;
  letter-spacing: 0.06em;
  color: #f5ead6;
}
.shop-section-head h2 .ico { width: 16px; height: 16px; color: var(--gold); }
.shop-section-head span { font-size: 10px; letter-spacing: 0.12em; text-transform: uppercase; color: var(--dim); }
.shop-cards { display: flex; flex-wrap: wrap; gap: clamp(10px, 1.6vw, 18px); }
.shop-item {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  padding: 8px 8px 6px;
  border-radius: 14px;
  border: 1px solid transparent;
  transition: 0.2s ease;
}
.shop-item .card { width: clamp(128px, 14.5vw, 176px); }
.shop-item:hover:not(.sold) { border-color: rgba(242, 193, 121, 0.18); background: rgba(255, 255, 255, 0.015); }
.shop-item.sold { opacity: 0.4; }
.shop-item.sold .card { pointer-events: none; }
.shop-item.unaffordable .card { filter: saturate(0.5) brightness(0.72); }
.shop-price {
  padding: 2px 9px;
  border-radius: 20px;
  background: rgba(242, 193, 121, 0.08);
  border: 1px solid rgba(242, 193, 121, 0.2);
  color: var(--gold);
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.03em;
}
.sold-tag {
  position: absolute;
  z-index: 4;
  top: 42%;
  left: 50%;
  transform: translate(-50%, -50%) rotate(-8deg);
  padding: 3px 12px;
  border: 1px solid rgba(255, 125, 125, 0.4);
  border-radius: 6px;
  background: rgba(20, 8, 10, 0.85);
  color: #ff9c9c;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.2em;
}
.shop-charms { display: flex; flex-wrap: wrap; gap: 12px; }
.shop-charm-item { position: relative; width: min(250px, 100%); }
.shop-charm-item .charm-tile { min-height: 192px; padding: 16px 14px 14px; }
.shop-charm-item .charm-big { width: 52px; height: 52px; margin-bottom: 4px; }
.shop-charm-item .charm-big .ico { width: 25px; height: 25px; }
.shop-charm-item .charm-halo { width: 72px; height: 72px; }
.shop-charm-item.sold { opacity: 0.45; }

.service-list { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
.service-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 14px;
  border-radius: 12px;
  border: 1px solid var(--line);
  background: linear-gradient(165deg, rgba(255, 255, 255, 0.03), rgba(255, 255, 255, 0.006));
}
.service-item.sold { opacity: 0.45; }
.service-ic {
  display: grid;
  place-items: center;
  width: 36px;
  height: 36px;
  flex: none;
  border-radius: 9px;
  border: 1px solid rgba(242, 193, 121, 0.18);
  background: rgba(242, 193, 121, 0.06);
  color: var(--gold);
}
.service-ic .ico { width: 18px; height: 18px; }
.service-txt { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.service-txt b { font-size: 12.5px; font-weight: 600; color: var(--text); }
.service-txt i { font-style: normal; font-size: 10.5px; line-height: 1.4; color: var(--dim); }
.service-item .btn { margin-left: auto; flex: none; }
.shop-footer {
  display: flex;
  justify-content: flex-end;
  margin-top: clamp(20px, 3vh, 32px);
  padding-top: 16px;
  border-top: 1px solid var(--line);
}

/* -------------------------------------------------------------------- camp */

.rest-screen { justify-content: flex-start; }
.rest-scene {
  position: relative;
  width: min(620px, 100%);
  height: clamp(150px, 23vh, 230px);
  display: flex;
  align-items: flex-end;
  justify-content: center;
  margin-bottom: -6px;
}
.campfire { position: relative; z-index: 2; width: clamp(150px, 18vw, 215px); filter: drop-shadow(0 12px 22px rgba(0, 0, 0, 0.45)); }
.rest-glow {
  position: absolute;
  left: 50%;
  bottom: 0;
  width: min(480px, 80%);
  height: 160%;
  transform: translateX(-50%);
  background: radial-gradient(ellipse at 50% 68%, rgba(255, 158, 62, 0.19), transparent 62%);
  filter: blur(6px);
  pointer-events: none;
}
.rest-result {
  margin-top: 18px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  text-align: center;
}
.rest-result p { font-size: 13px; color: var(--muted); }
.rest-result .btn { margin-top: 10px; }
.rest-options {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
  width: min(720px, 100%);
  margin-top: 18px;
}
.rest-option {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  padding: 18px 12px 15px;
  border-radius: 13px;
  border: 1px solid var(--line);
  background: linear-gradient(165deg, rgba(255, 255, 255, 0.035), rgba(255, 255, 255, 0.006));
  color: var(--text);
  cursor: pointer;
  text-align: center;
  transition: 0.2s ease;
}
.rest-option:hover:not(:disabled) {
  transform: translateY(-3px);
  border-color: rgba(242, 193, 121, 0.4);
  background: linear-gradient(165deg, rgba(242, 193, 121, 0.07), rgba(255, 255, 255, 0.008));
}
.rest-option:disabled { opacity: 0.35; cursor: not-allowed; }
.rest-ic {
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  margin-bottom: 4px;
  border-radius: 50%;
  border: 1px solid rgba(242, 193, 121, 0.2);
  background: rgba(242, 193, 121, 0.06);
  color: var(--gold);
}
.rest-ic .ico { width: 20px; height: 20px; }
.rest-option b { font-family: var(--serif); font-size: 14px; letter-spacing: 0.06em; }
.rest-option i { font-style: normal; font-size: 10.5px; line-height: 1.45; color: var(--dim); }

/* ------------------------------------------------------------------- glade */

.glade-screen { justify-content: flex-start; }
.glade-head { position: relative; text-align: center; max-width: 620px; }
.glade-glow {
  position: absolute;
  left: 50%;
  top: -30px;
  width: 520px;
  height: 300px;
  transform: translateX(-50%);
  background: radial-gradient(ellipse at center, rgba(127, 216, 210, 0.09), transparent 65%);
  pointer-events: none;
}
.glade-head h1 { margin-top: 8px; }
.glade-head p { margin-top: 10px; font-size: 12.5px; line-height: 1.6; color: var(--dim); }
.glade-options {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: clamp(10px, 1.6vw, 18px);
  width: min(1060px, 100%);
  margin-top: clamp(20px, 3vh, 30px);
}
.glade-option {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 4px;
  padding: 16px 16px 18px;
  border-radius: 16px;
  border: 1px solid var(--line);
  background:
    radial-gradient(80% 60% at 50% 4%, rgba(127, 216, 210, 0.06), transparent 62%),
    linear-gradient(170deg, rgba(25, 35, 48, 0.72), rgba(10, 15, 24, 0.85));
  color: var(--text);
  cursor: pointer;
  overflow: hidden;
  transition: 0.22s ease;
  animation: riseIn 0.5s ease both;
}
.glade-option:nth-child(2) { animation-delay: 0.06s; }
.glade-option:nth-child(3) { animation-delay: 0.12s; }
.glade-option:hover {
  transform: translateY(-5px);
  border-color: rgba(127, 216, 210, 0.36);
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.35), 0 0 28px rgba(127, 216, 210, 0.07);
}
.glade-figure {
  display: flex;
  align-items: flex-end;
  justify-content: center;
  height: clamp(120px, 16vw, 170px);
  width: 100%;
  margin-bottom: 4px;
  filter: drop-shadow(0 14px 16px rgba(0, 0, 0, 0.4));
}
.glade-figure .art-svg { height: 100%; width: auto; }
.glade-info { display: flex; flex-direction: column; align-items: center; gap: 3px; width: 100%; }
.glade-name { font-family: var(--serif); font-size: clamp(18px, 2vw, 24px); font-weight: 700; color: #fbf2df; line-height: 1.1; }
.glade-lore { margin-top: 5px; font-size: 10.5px; line-height: 1.5; font-style: italic; color: var(--dim); min-height: 32px; }
.glade-trait {
  margin-top: 6px;
  padding: 5px 8px;
  border-radius: 7px;
  background: rgba(255, 255, 255, 0.025);
  border: 1px solid var(--line);
  font-size: 9.5px;
  line-height: 1.4;
  color: var(--dim);
}
.glade-trait b { display: block; color: var(--gold); font-weight: 600; }
.glade-sig { margin-top: 6px; font-size: 10px; color: var(--muted); }
.glade-sig .ico { color: var(--rose); width: 11px; height: 11px; }
.glade-sig b { color: var(--rose); }
.glade-screen .result-actions { margin-top: 18px; }

/* ==========================================================================
   WILDBOUND — end screens, modals, catch overlay, FX, toasts
   ========================================================================== */

/* -------------------------------------------------------------- end states */

.end-screen {
  position: relative;
  min-height: 100%;
  height: 100%;
  overflow: hidden auto;
  display: grid;
  place-items: center;
  isolation: isolate;
  background:
    radial-gradient(90% 70% at 50% 0%, rgba(60, 55, 72, 0.35), transparent 60%),
    linear-gradient(180deg, #0a1220 0%, #080d16 52%, #05070c 100%);
}
.end-sky { position: absolute; inset: 0; z-index: 0; overflow: hidden; }
.end-sky::before {
  content: '';
  position: absolute;
  inset: 0;
  opacity: 0.6;
  background-image:
    radial-gradient(1px 1px at 22% 18%, rgba(255, 244, 214, 0.5), transparent 60%),
    radial-gradient(1px 1px at 68% 30%, rgba(255, 244, 214, 0.3), transparent 60%),
    radial-gradient(1.4px 1.4px at 82% 12%, rgba(255, 244, 214, 0.38), transparent 60%);
  background-size: 320px 260px, 420px 330px, 280px 230px;
}
.end-sky::after {
  content: '';
  position: absolute;
  left: -5%;
  right: -5%;
  bottom: 0;
  height: 30%;
  background: #06090f;
  clip-path: polygon(0 100%, 0 55%, 8% 40%, 15% 58%, 24% 34%, 33% 59%, 42% 42%, 51% 64%, 61% 38%, 70% 60%, 79% 33%, 88% 57%, 95% 44%, 100% 58%, 100% 100%);
  opacity: 0.9;
}
.end-glow {
  position: absolute;
  z-index: 1;
  left: 50%;
  top: 18%;
  width: 70vw;
  height: 70vw;
  max-width: 880px;
  max-height: 880px;
  transform: translateX(-50%);
  border-radius: 50%;
  background: radial-gradient(circle, rgba(255, 206, 116, 0.14), transparent 62%);
  filter: blur(8px);
  pointer-events: none;
}
.end-glow.red { background: radial-gradient(circle, rgba(255, 92, 92, 0.1), transparent 62%); }
.end-creature {
  position: absolute;
  z-index: 1;
  left: 50%;
  top: 52%;
  width: min(54vw, 560px);
  transform: translate(-50%, -50%);
  opacity: 0.22;
  filter: drop-shadow(0 30px 50px rgba(0, 0, 0, 0.7)) blur(0.6px);
  pointer-events: none;
}
.end-creature.dim { opacity: 0.12; }
.end-content {
  position: relative;
  z-index: 3;
  width: min(760px, 100%);
  padding: clamp(30px, 6vh, 64px) clamp(18px, 4vw, 34px) calc(34px + env(safe-area-inset-bottom, 0px));
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  animation: riseIn 0.7s ease both;
}
.end-content h1 { margin-top: 10px; font-size: clamp(44px, 6.4vw, 78px); }
.end-flavor {
  max-width: 610px;
  margin-top: 16px;
  font-size: clamp(13px, 1.4vw, 15px);
  line-height: 1.72;
  font-weight: 300;
  color: var(--muted);
}
.end-stats {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
  width: min(600px, 100%);
  margin-top: clamp(20px, 3.4vh, 30px);
}
.end-stats > div {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 11px 6px 9px;
  border-radius: 10px;
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.022);
}
.end-stats b { font-family: var(--serif); font-size: clamp(20px, 2.6vw, 30px); line-height: 1; color: var(--gold-bright); font-weight: 700; }
.end-stats span { margin-top: 4px; font-size: 8px; letter-spacing: 0.1em; text-transform: uppercase; color: var(--dim); }
.end-caught { width: min(740px, 100%); margin-top: 22px; }
.end-caught .eyebrow { font-size: 8px; letter-spacing: 0.2em; }
.caught-row { display: flex; flex-wrap: wrap; justify-content: center; gap: 8px; margin-top: 9px; }
.caught-mini {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  width: 58px;
  padding: 5px 3px 4px;
  border-radius: 9px;
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.02);
}
.caught-mini .art-svg { height: 34px; width: auto; }
.caught-mini i { font-style: normal; font-size: 7px; letter-spacing: 0.02em; color: var(--dim); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 100%; }
.end-tip {
  display: flex;
  align-items: flex-start;
  gap: 7px;
  max-width: 560px;
  margin-top: 20px;
  padding: 9px 12px;
  border-radius: 9px;
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.02);
  font-size: 10.5px;
  line-height: 1.5;
  color: var(--dim);
  text-align: left;
}
.end-tip .ico { color: var(--gold-deep); width: 14px; height: 14px; flex: none; margin-top: 1px; }
.end-actions { display: flex; gap: 10px; flex-wrap: wrap; justify-content: center; margin-top: clamp(22px, 4vh, 34px); }
.victory-screen.pact-end .end-creature { opacity: 0.3; }
.victory-screen.pact-end .end-glow { background: radial-gradient(circle, rgba(255, 159, 196, 0.16), rgba(255, 206, 116, 0.08) 45%, transparent 66%); }
.victory-screen.pact-end .end-content h1 { background: linear-gradient(180deg, #fff8e8, #ffd98f 46%, #ff9fc4 100%); -webkit-background-clip: text; background-clip: text; color: transparent; }
.victory-screen.pact-end .end-sky::before { background-image:
  radial-gradient(1.2px 1.2px at 22% 18%, rgba(255, 220, 236, 0.65), transparent 60%),
  radial-gradient(1.2px 1.2px at 68% 30%, rgba(255, 244, 214, 0.45), transparent 60%),
  radial-gradient(1.8px 1.8px at 82% 12%, rgba(255, 214, 234, 0.5), transparent 60%);
  background-size: 320px 260px, 420px 330px, 280px 230px;
}

/* ------------------------------------------------------------------ modals */

.modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 200;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: calc(12px + env(safe-area-inset-top, 0px)) 12px calc(12px + env(safe-area-inset-bottom, 0px));
  background: rgba(4, 7, 11, 0.74);
  backdrop-filter: blur(7px);
  -webkit-backdrop-filter: blur(7px);
  animation: fadeIn 0.18s ease both;
}
@keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
.modal {
  display: flex;
  flex-direction: column;
  width: min(600px, calc(100vw - 24px));
  max-height: min(88vh, 900px);
  max-height: min(88dvh, 900px);
  border-radius: 18px;
  border: 1px solid rgba(255, 235, 200, 0.18);
  background:
    radial-gradient(90% 50% at 50% 0%, rgba(242, 193, 121, 0.045), transparent 62%),
    linear-gradient(180deg, #151d2b, #0b1019);
  box-shadow: 0 40px 90px rgba(0, 0, 0, 0.65), inset 0 1px 0 rgba(255, 255, 255, 0.06);
  animation: modalIn 0.26s cubic-bezier(0.2, 0.75, 0.25, 1) both;
  overflow: hidden;
}
.modal.wide { width: min(980px, calc(100vw - 24px)); }
@keyframes modalIn { from { opacity: 0; transform: translateY(12px) scale(0.985); } to { opacity: 1; transform: none; } }
.modal-head {
  position: relative;
  flex: none;
  padding: 18px 58px 14px 22px;
  border-bottom: 1px solid var(--line);
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.02), transparent);
}
.modal-head h2 {
  margin-top: 4px;
  font-family: var(--serif);
  font-size: clamp(22px, 2.6vw, 30px);
  font-weight: 700;
  letter-spacing: 0.02em;
  color: #fbf2df;
  line-height: 1.1;
}
.modal-close {
  position: absolute;
  top: 16px;
  right: 16px;
  display: grid;
  place-items: center;
  width: 32px;
  height: 32px;
  border-radius: 8px;
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.03);
  color: var(--dim);
  cursor: pointer;
}
.modal-close .ico { width: 14px; height: 14px; }
.modal-close:hover { color: var(--text); border-color: var(--line-strong); }
.modal-body { flex: 1; min-height: 0; overflow-y: auto; padding: 18px 22px 24px; overscroll-behavior: contain; }
.modal-note {
  margin-bottom: 14px;
  padding: 8px 11px;
  border-radius: 8px;
  border: 1px solid rgba(242, 193, 121, 0.16);
  background: rgba(242, 193, 121, 0.045);
  font-size: 11px;
  line-height: 1.5;
  color: var(--muted);
}

.deck-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(132px, 1fr));
  gap: 10px;
  align-items: start;
}
.deck-cell { position: relative; display: flex; justify-content: center; }
.deck-cell .card { width: 100%; }
.deck-cell.maxed .card { filter: saturate(0.6) brightness(0.8); }
.deck-cell.locked { opacity: 0.4; pointer-events: none; }
.cell-tag {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%) rotate(-8deg);
  padding: 2px 8px;
  border-radius: 5px;
  border: 1px solid rgba(242, 193, 121, 0.4);
  background: rgba(10, 12, 18, 0.85);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.16em;
  color: var(--gold);
  pointer-events: none;
}

.dex-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 2px 2px 14px;
  margin-bottom: 16px;
  border-bottom: 1px solid var(--line);
  flex-wrap: wrap;
}
.dex-count { display: flex; align-items: baseline; gap: 6px; }
.dex-count b { font-family: var(--serif); font-size: 32px; color: var(--gold-bright); line-height: 1; }
.dex-count span { font-size: 11px; color: var(--dim); }
.dex-total { display: inline-flex; align-items: center; gap: 5px; font-size: 10.5px; color: var(--muted); }
.dex-total .ico { color: var(--rose); width: 13px; height: 13px; }
.dex-tier { margin-bottom: 18px; }
.dex-tier > .eyebrow { margin-bottom: 8px; display: block; font-size: 8px; letter-spacing: 0.2em; }
.dex-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
  gap: 8px;
}

.help-intro p { font-size: 13px; line-height: 1.65; color: var(--muted); }
.help-intro em { color: var(--gold-bright); font-style: italic; }
.help-intro b { color: var(--text); }
.help-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-top: 16px; }
.help-sec {
  padding: 13px 14px;
  border-radius: 10px;
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.02);
}
.help-sec h3 {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 6px;
  font-family: var(--serif);
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.04em;
  color: var(--gold-bright);
}
.help-sec h3 .ico { width: 14px; height: 14px; color: var(--gold); }
.help-sec p { font-size: 11px; line-height: 1.55; color: var(--dim); }
.help-sec p + p { margin-top: 6px; }
.help-sec b { color: var(--muted); }
.help-sec.catch-help { border-color: rgba(255, 159, 196, 0.2); background: rgba(255, 159, 196, 0.025); }
.help-sec.catch-help h3 { color: var(--rose); }
.help-sec.catch-help h3 .ico { color: var(--rose); }
.catch-diagram {
  margin-top: 14px;
  padding: 12px 14px;
  border-radius: 10px;
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.02);
}
.catch-diagram-bar {
  position: relative;
  height: 17px;
  border-radius: 20px;
  background: #1b1319;
  border: 1px solid rgba(255, 255, 255, 0.1);
  overflow: hidden;
}
.catch-diagram-bar span { display: block; height: 100%; background: linear-gradient(90deg, #7c2e3c, #d8616b); }
.catch-diagram-bar i {
  position: absolute;
  top: -2px;
  bottom: -2px;
  border-left: 1.5px dashed #ffdf9e;
  font-style: normal;
  font-size: 6px;
  color: #ffdf9e;
  padding: 1px 0 0 4px;
  letter-spacing: 0.1em;
  white-space: nowrap;
}
.catch-diagram-text { margin-top: 7px; font-size: 10px; color: var(--dim); }
.help-statuses { margin-top: 16px; }
.help-statuses > .eyebrow { font-size: 8px; letter-spacing: 0.2em; margin-bottom: 8px; }
.status-glossary { display: grid; grid-template-columns: 1fr 1fr; gap: 5px; }
.gloss {
  display: flex;
  align-items: flex-start;
  gap: 5px;
  padding: 6px 8px;
  border-radius: 7px;
  border: 1px solid color-mix(in srgb, var(--c) 18%, var(--line));
  background: color-mix(in srgb, var(--c) 4%, transparent);
  font-size: 9.5px;
  line-height: 1.4;
  color: var(--dim);
}
.gloss .ico { width: 12px; height: 12px; color: var(--c); flex: none; margin-top: 1px; }
.gloss b { color: var(--c); font-weight: 600; white-space: nowrap; }
.gloss i { font-style: normal; }
.help-keys {
  display: flex;
  flex-wrap: wrap;
  gap: 10px 16px;
  margin-top: 16px;
  padding-top: 12px;
  border-top: 1px solid var(--line);
  font-size: 10px;
  color: var(--dim);
}
.help-keys span { display: inline-flex; align-items: center; gap: 4px; }

.menu-run {
  display: flex;
  flex-direction: column;
  gap: 1px;
  margin-bottom: 16px;
  border: 1px solid var(--line);
  border-radius: 9px;
  overflow: hidden;
}
.menu-run-line {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 8px 11px;
  background: rgba(255, 255, 255, 0.018);
  font-size: 11px;
  color: var(--dim);
}
.menu-run-line + .menu-run-line { border-top: 1px solid var(--line); }
.menu-run-line b { color: var(--gold); font-weight: 600; letter-spacing: 0.04em; }
.menu-buttons { display: flex; flex-direction: column; gap: 7px; }
.menu-buttons .btn { justify-content: flex-start; }
.menu-note { margin-top: 13px; font-size: 9.5px; line-height: 1.5; color: var(--dim); text-align: center; }
.confirm-copy { font-size: 13px; line-height: 1.65; color: var(--muted); }
.confirm-actions { display: flex; gap: 8px; justify-content: flex-end; flex-wrap: wrap; margin-top: 18px; }
.confirm-modal { width: min(460px, calc(100vw - 24px)); }

.notes-grid { display: grid; gap: 8px; }
.note-item { display: grid; grid-template-columns: 28px 1fr; gap: 2px 8px; padding: 9px 10px; border: 1px solid var(--line); border-radius: 9px; }
.note-item > span { grid-row: span 2; color: var(--gold); }
.note-item > span .ico { width: 18px; height: 18px; }
.note-item b { font-size: 12px; color: var(--text); }
.note-item p { font-size: 10.5px; line-height: 1.5; color: var(--dim); }

/* --------------------------------------------------------- catch animation */

.catch-overlay {
  position: fixed;
  inset: 0;
  z-index: 500;
  display: grid;
  place-items: center;
  overflow: hidden;
  pointer-events: none;
}
.catch-overlay-dim {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(circle at 50% 46%, rgba(255, 159, 196, 0.12) 0%, rgba(6, 9, 14, 0.84) 55%, rgba(4, 6, 10, 0.94) 100%);
  animation: catchDim 1.75s ease both;
}
@keyframes catchDim {
  0% { opacity: 0; }
  15%, 78% { opacity: 1; }
  100% { opacity: 0; }
}
.catch-overlay-kin {
  position: absolute;
  left: 50%;
  top: 48%;
  width: clamp(190px, 28vw, 340px);
  transform: translate(-50%, -50%);
  filter: drop-shadow(0 30px 40px rgba(0, 0, 0, 0.55));
  animation: catchKin 1.75s cubic-bezier(0.2, 0.75, 0.25, 1) both;
}
@keyframes catchKin {
  0% { opacity: 0; transform: translate(-50%, -44%) scale(0.55); filter: brightness(2.4) blur(6px); }
  26% { opacity: 1; transform: translate(-50%, -50%) scale(1.04); filter: brightness(1.35) blur(0); }
  50% { transform: translate(-50%, -50%) scale(1); filter: brightness(1); }
  72% { filter: brightness(1.6); }
  100% { opacity: 0; transform: translate(-50%, -54%) scale(1.12); filter: brightness(2.4) blur(3px); }
}
.thrown-orb {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 44px;
  height: 44px;
  margin: -22px 0 0 -22px;
  border-radius: 50%;
  background: radial-gradient(circle at 38% 30%, #fff3c8, #f2b860 54%, #9e5c1f 100%);
  border: 2px solid #ffe9b0;
  box-shadow: 0 0 30px rgba(255, 205, 120, 0.7);
  animation: throwOrb 1.15s cubic-bezier(0.3, 0.6, 0.4, 1) both;
}
.thrown-orb span {
  position: absolute;
  inset: 5px;
  border-radius: 50%;
  border: 1px solid rgba(90, 45, 12, 0.55);
}
@keyframes throwOrb {
  0% { opacity: 1; transform: translate(0, 44vh) scale(0.5) rotate(0deg); }
  52% { opacity: 1; transform: translate(0, 0) scale(1) rotate(360deg); }
  68% { transform: translate(0, -14px) scale(1.05) rotate(380deg); }
  85% { transform: translate(0, 0) scale(1) rotate(360deg); opacity: 1; }
  100% { transform: translate(0, 0) scale(2.4) rotate(360deg); opacity: 0; }
}
.catch-burst {
  position: absolute;
  left: 50%;
  top: 48%;
  width: 280px;
  height: 280px;
  margin: -140px 0 0 -140px;
  border-radius: 50%;
  border: 2px solid rgba(255, 196, 216, 0.65);
  animation: catchBurst 1s 0.62s cubic-bezier(0.2, 0.7, 0.3, 1) both;
}
@keyframes catchBurst {
  0% { opacity: 0; transform: scale(0.2); }
  18% { opacity: 1; }
  100% { opacity: 0; transform: scale(2.3); }
}
.catch-word {
  position: absolute;
  left: 50%;
  bottom: 18%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  text-align: center;
  animation: catchWord 1.5s 0.55s ease both;
}
.catch-word span {
  font-family: var(--serif);
  font-size: clamp(22px, 3.2vw, 38px);
  font-weight: 700;
  letter-spacing: 0.24em;
  margin-left: 0.24em;
  color: #ffe9c6;
  text-shadow: 0 0 28px rgba(255, 196, 216, 0.4), 0 2px 10px #000;
}
.catch-word i { font-size: 10px; letter-spacing: 0.24em; text-transform: uppercase; color: var(--rose); font-style: normal; }
@keyframes catchWord {
  0% { opacity: 0; transform: translate(-50%, 10px); }
  20%, 72% { opacity: 1; transform: translate(-50%, 0); }
  100% { opacity: 0; transform: translate(-50%, -6px); }
}
.catch-overlay.boss .thrown-orb { box-shadow: 0 0 50px rgba(255, 227, 154, 0.9); }
.catch-overlay.boss .catch-word span { color: #fff1c4; text-shadow: 0 0 34px rgba(255, 220, 130, 0.55), 0 2px 10px #000; }

/* -------------------------------------------------------------------- FX */

.fx-num {
  position: absolute;
  transform: translate(-50%, -50%);
  font-family: var(--serif);
  font-size: 27px;
  font-weight: 700;
  color: #ffe8d0;
  text-shadow: 0 2px 6px #000, 0 0 16px rgba(0, 0, 0, 0.5);
  animation: fxFloat 1.05s cubic-bezier(0.2, 0.7, 0.3, 1) forwards;
  white-space: nowrap;
  will-change: transform, opacity;
}
.fx-num.dmg { color: #ff9c8f; }
.fx-num.poison { color: #c8f58b; }
.fx-num.burn { color: #ffb066; }
.fx-num.block { color: #a9dcff; font-size: 16px; font-family: var(--sans); font-weight: 700; letter-spacing: 0.04em; }
.fx-num.heal { color: #9ef0b4; }
.fx-num.buff { color: #ffe08a; font-size: 16px; font-family: var(--sans); font-weight: 700; }
.fx-num.status { color: #d9bcff; font-size: 15px; font-family: var(--sans); font-weight: 600; }
.fx-num.status-small { color: #cfc2b0; font-size: 10px; font-family: var(--sans); font-weight: 600; letter-spacing: 0.12em; }
.fx-num.draw { color: var(--teal); font-size: 13px; font-family: var(--sans); font-weight: 700; letter-spacing: 0.1em; }
.fx-num.energy { color: var(--gold-bright); font-size: 15px; font-family: var(--sans); font-weight: 700; letter-spacing: 0.08em; }
@keyframes fxFloat {
  0% { opacity: 0; transform: translate(-50%, -30%) scale(0.7); }
  18% { opacity: 1; transform: translate(-50%, -60%) scale(1.12); }
  55% { transform: translate(-50%, -118%) scale(1); opacity: 1; }
  100% { opacity: 0; transform: translate(-50%, -185%) scale(0.92); }
}
.fx-spark {
  position: absolute;
  border-radius: 50%;
  pointer-events: none;
  animation: sparkFly var(--dur, 700ms) cubic-bezier(0.15, 0.7, 0.3, 1) forwards;
}
@keyframes sparkFly {
  0% { opacity: 1; transform: translate(0, 0) scale(1); }
  100% { opacity: 0; transform: translate(var(--dx), var(--dy)) scale(0.2) rotate(var(--rot)); }
}
.fx-flash {
  position: fixed;
  inset: 0;
  pointer-events: none;
  animation: flashFade 0.38s ease-out forwards;
}
.fx-flash.red { background: radial-gradient(circle at 50% 45%, rgba(255, 70, 70, 0.12), rgba(255, 40, 40, 0.24) 100%); }
.fx-flash.soft { background: radial-gradient(circle at 50% 45%, rgba(255, 180, 120, 0.06), rgba(255, 120, 100, 0.12) 100%); }
@keyframes flashFade { 0% { opacity: 0; } 25% { opacity: 1; } 100% { opacity: 0; } }
.fx-banner {
  position: fixed;
  z-index: 420;
  top: 17%;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  width: min(92vw, 640px);
  padding: 10px 26px;
  border-radius: 4px;
  text-align: center;
  background: linear-gradient(90deg, transparent, rgba(7, 10, 16, 0.86) 18%, rgba(7, 10, 16, 0.86) 82%, transparent);
  animation: bannerIn 0.4s cubic-bezier(0.2, 0.75, 0.25, 1) both;
  pointer-events: none;
}
.fx-banner::before, .fx-banner::after {
  content: '';
  position: absolute;
  left: 50%;
  width: 60%;
  height: 1px;
  transform: translateX(-50%);
  background: linear-gradient(90deg, transparent, rgba(242, 193, 121, 0.4), transparent);
}
.fx-banner::before { top: 0; }
.fx-banner::after { bottom: 0; }
.fx-banner b {
  font-family: var(--serif);
  font-size: clamp(15px, 2vw, 22px);
  font-weight: 700;
  letter-spacing: 0.18em;
  color: #ffe3a8;
  text-shadow: 0 2px 10px #000;
}
.fx-banner span { font-size: 10px; letter-spacing: 0.1em; color: var(--muted); }
.fx-banner.enemy b { color: #ffb4a4; }
.fx-banner.phase b { color: #fff3c6; font-size: clamp(18px, 2.4vw, 26px); }
.fx-banner.out { animation: bannerOut 0.45s ease both; }
@keyframes bannerIn { from { opacity: 0; transform: translate(-50%, -10px); } to { opacity: 1; transform: translate(-50%, 0); } }
@keyframes bannerOut { to { opacity: 0; transform: translate(-50%, -8px); } }
.cast-clone {
  position: fixed;
  z-index: 450;
  pointer-events: none;
  transform-origin: 50% 50%;
}

.toast {
  padding: 9px 16px;
  border-radius: 9px;
  border: 1px solid rgba(255, 235, 200, 0.2);
  background: rgba(15, 21, 32, 0.96);
  color: var(--text);
  font-size: 12px;
  font-weight: 500;
  box-shadow: 0 14px 32px rgba(0, 0, 0, 0.42);
  backdrop-filter: blur(12px);
  animation: toastIn 0.28s cubic-bezier(0.2, 0.75, 0.25, 1) both;
  max-width: 100%;
  text-align: center;
}
.toast.good { border-color: rgba(143, 226, 166, 0.34); color: #c8f3d2; }
.toast.bad { border-color: rgba(255, 125, 125, 0.38); color: #ffc0c0; }
.toast.out { animation: toastOut 0.35s ease both; }
@keyframes toastIn { from { opacity: 0; transform: translateY(-8px) scale(0.97); } to { opacity: 1; transform: none; } }
@keyframes toastOut { to { opacity: 0; transform: translateY(-6px) scale(0.98); } }

.shake { animation: shake 0.42s cubic-bezier(0.36, 0.07, 0.19, 0.97) both; }
.shake-hard { animation: shakeHard 0.48s cubic-bezier(0.36, 0.07, 0.19, 0.97) both; }
@keyframes shake {
  10%, 90% { transform: translateX(-2px); }
  20%, 80% { transform: translateX(4px); }
  30%, 50%, 70% { transform: translateX(-6px); }
  40%, 60% { transform: translateX(6px); }
}
@keyframes shakeHard {
  10%, 90% { transform: translate(-3px, 1px); }
  20%, 80% { transform: translate(7px, -2px); }
  30%, 50%, 70% { transform: translate(-10px, 2px); }
  40%, 60% { transform: translate(10px, -1px); }
}

/* -------------------------------------------------------------- motion off */

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}
html.reduced-motion *, html.reduced-motion *::before, html.reduced-motion *::after {
  animation-duration: 0.01ms !important;
  animation-iteration-count: 1 !important;
  transition-duration: 0.01ms !important;
}

/* ==========================================================================
   WILDBOUND — responsive layout (desktop, tablet, phone, landscape)
   ========================================================================== */

@media (max-width: 1220px) {
  .map-screen { grid-template-columns: minmax(0, 1fr) 300px; }
  .title-creature { width: clamp(140px, 15vw, 210px); }
  .title-creature.small { width: clamp(76px, 7.5vw, 110px); }
}

@media (max-width: 1020px) {
  .map-screen { grid-template-columns: minmax(0, 1fr) 278px; gap: 14px; }
  .map-head p { font-size: 11.5px; }
  .enemy-side { width: clamp(200px, 31vw, 300px); }
  .player-side { width: clamp(130px, 17vw, 180px); }
